def load(kind, ck):
    if kind == 'frcnn':
        from torchvision.models.detection import fasterrcnn_resnet50_fpn_v2
        m = fasterrcnn_resnet50_fpn_v2(weights=None, weights_backbone=None, num_classes=3)
        st = torch.load(ck, map_location='cpu')
        if isinstance(st, dict) and not any(k.startswith(('backbone', 'rpn', 'roi_heads')) for k in st):
            st = st.get('model', st.get('state_dict', st))
        m.load_state_dict(st)
        x = [torch.rand(3, 640, 640, device=dev)]
        return m.eval().to(dev), (lambda mm: mm(x))
    from ultralytics import YOLO, RTDETR
    m = (RTDETR if kind == 'rtdetr' else YOLO)(ck).model.float().eval().to(dev)
    x = torch.rand(1, 3, 640, 640, device=dev)
    return m, (lambda mm: mm(x))


rows = []
for name, (kind, ck) in MODELS.items():
    if not os.path.exists(ck):
        print('MISSING', name, ck); continue
    m, run = load(kind, ck)
    with torch.no_grad():
        for _ in range(WARM): run(m)
        t = []
        for _ in range(RUNS_N):
            torch.cuda.synchronize(); s = time.perf_counter()
            run(m)
            torch.cuda.synchronize(); t.append((time.perf_counter() - s) * 1000)
    rows.append((name, np.mean(t), np.std(t)))
    print(f'{name:14s} {np.mean(t):7.2f} ms  (SD {np.std(t):.2f})')
    del m; torch.cuda.empty_cache()

print('\nPaste into Table 2 (Infer, ms/img):')
