# COUNT IMAGES & ANNOTATIONS PER SPLIT (YOLO format: images/ + labels/ dirs)
# ─────────────────────────────────────────────────────────────────────────────
import os, glob

def count_split(images_dir):
    labels_dir = images_dir.replace('/images', '/labels')

    img_exts = ('*.jpg', '*.jpeg', '*.png', '*.bmp')
    image_files = []
    for ext in img_exts:
        image_files.extend(glob.glob(os.path.join(images_dir, ext)))

    label_files = glob.glob(os.path.join(labels_dir, '*.txt'))

    n_images = len(image_files)
    n_annotations = 0
    n_empty_labels = 0
    class_counts = {}

    for lf in label_files:
        with open(lf, 'r') as f:
            lines = [l.strip() for l in f.readlines() if l.strip()]
        if len(lines) == 0:
            n_empty_labels += 1
        for line in lines:
            cls_id = line.split()[0]
            class_counts[cls_id] = class_counts.get(cls_id, 0) + 1
        n_annotations += len(lines)

    return {
        'images_dir': images_dir,
        'labels_dir': labels_dir,
        'n_images': n_images,
        'n_label_files': len(label_files),
        'n_annotations': n_annotations,
        'n_empty_labels': n_empty_labels,
        'class_counts': class_counts,
    }

splits = {
    'train': data_yaml['train'],
    'valid': data_yaml['val'],
    'test':  data_yaml['test'],
}

names = data_yaml['names']
summary = {}

for split_name, img_dir in splits.items():
    stats = count_split(img_dir)
    summary[split_name] = stats

    print(f"\n{'='*60}")
    print(f"SPLIT: {split_name.upper()}")
    print(f"{'='*60}")
    print(f"Images dir      : {stats['images_dir']}")
    print(f"Labels dir      : {stats['labels_dir']}")
    print(f"# Images        : {stats['n_images']}")
    print(f"# Label files   : {stats['n_label_files']}")
    print(f"# Annotations   : {stats['n_annotations']}")
    print(f"# Empty labels  : {stats['n_empty_labels']}  (images with no bbox)")
    print(f"Per-class count :")
    for cls_id, cnt in sorted(stats['class_counts'].items(), key=lambda x: int(x[0])):
        cls_name = names[int(cls_id)] if int(cls_id) < len(names) else f"class_{cls_id}"
        print(f"    [{cls_id}] {cls_name:20s}: {cnt}")

# ─────────────────────────────────────────────────────────────────────────────
# GRAND TOTALS
# ─────────────────────────────────────────────────────────────────────────────
total_images = sum(s['n_images'] for s in summary.values())
total_annots = sum(s['n_annotations'] for s in summary.values())

print(f"\n{'='*60}")
print("GRAND TOTAL")
print(f"{'='*60}")
print(f"Total images      : {total_images}")
print(f"Total annotations : {total_annots}")
for split_name, s in summary.items():
    pct = 100 * s['n_images'] / total_images if total_images else 0
    print(f"  {split_name:6s}: {s['n_images']:5d} images ({pct:5.1f}%), {s['n_annotations']:5d} annotations")

