# ─────────────────────────────────────────────────────────────────────────────
# ADDED — Faster R-CNN load/predict helpers (identical to the trimmed script)
# ─────────────────────────────────────────────────────────────────────────────
def load_faster_rcnn(ckpt_path, num_classes=NC + 1, device=TORCH_DEV):
    """fasterrcnn_resnet50_fpn_v2 — matches how FasterRCNN/best.pth was
    trained (BN-equipped FPN blocks, conv-based box head)."""
    model = fasterrcnn_resnet50_fpn_v2(weights=None, num_classes=num_classes)
    state = torch.load(ckpt_path, map_location='cpu')
    if isinstance(state, dict) and 'model' in state and not any(
        k.startswith(('backbone', 'rpn', 'roi_heads')) for k in state.keys()
    ):
        state = state['model']
    elif isinstance(state, dict) and 'state_dict' in state and not any(
        k.startswith(('backbone', 'rpn', 'roi_heads')) for k in state.keys()
    ):
        state = state['state_dict']
    model.load_state_dict(state)
    model.eval()
    model.to(device)
    return model


def frcnn_predict(model, image_path, conf=CONF_THR, device=TORCH_DEV):
    """Returns boxes/scores/labels in 0-indexed class convention (matches
    YOLO), since torchvision labels are 1-indexed with 0=background."""
    img = PILImage.open(image_path).convert('RGB')
    tensor = TF.to_tensor(img).to(device)
    with torch.no_grad():
        out = model([tensor])[0]
    boxes  = out['boxes'].cpu().numpy()
    scores = out['scores'].cpu().numpy()
    labels = out['labels'].cpu().numpy().astype(np.int64) - 1
    keep = scores >= conf
    return boxes[keep], scores[keep], labels[keep]


