class CariesDataset(Dataset):
    def __init__(self, img_dir, lbl_dir, transforms=None):
        self.img_paths  = sorted(
            glob.glob(os.path.join(img_dir, '*.jpg')) +
            glob.glob(os.path.join(img_dir, '*.png'))
        )
        self.lbl_dir    = lbl_dir
        self.transforms = transforms

    def __len__(self): return len(self.img_paths)

    def __getitem__(self, idx):
        img_path = self.img_paths[idx]
        img      = PILImage.open(img_path).convert('RGB')
        W, H     = img.size
        lbl_path = os.path.join(
            self.lbl_dir,
            os.path.splitext(os.path.basename(img_path))[0] + '.txt'
        )
        boxes, labels = [], []
        if os.path.exists(lbl_path):
            with open(lbl_path) as f:
                for line in f:
                    parts = line.strip().split()
                    if len(parts) < 5: continue
                    cls, cx, cy, bw, bh = map(float, parts[:5])
                    x1 = (cx - bw/2)*W;  y1 = (cy - bh/2)*H
                    x2 = (cx + bw/2)*W;  y2 = (cy + bh/2)*H
                    boxes.append([x1, y1, x2, y2])
                    labels.append(int(cls))          # 0-indexed for per-class
        boxes  = torch.tensor(boxes,  dtype=torch.float32) if boxes  else torch.zeros((0,4))
        labels = torch.tensor(labels, dtype=torch.int64)   if labels else torch.zeros((0,), dtype=torch.int64)
        target = {'boxes': boxes, 'labels': labels,
                  'image_id': torch.tensor([idx]), 'img_path': img_path}
        if self.transforms:
            img = self.transforms(img)
        return img, target

    def get_all_img_paths(self): return self.img_paths


def collate_fn(batch): return tuple(zip(*batch))

