def evaluate_model_on_loader(weights_path, model_type, loader, conf=CONF_THR, iou=IOU_THR):
    """
    Returns
    -------
    records : list of dict — one entry per image with per-class TP/FP/FN
    all_preds / all_targets : for torchmetrics mAP
    per_class_scores : dict[class_idx] → list of (score, is_tp)  for ROC
    """
    if model_type == 'frcnn':
        model = load_faster_rcnn(weights_path)
    else:
        model = YOLO(weights_path)

    records, all_preds, all_targets = [], [], []
    per_class_scores = {c: [] for c in range(NC)}

    for imgs, targets in loader:
        img_paths = [t['img_path'] for t in targets]

        if model_type == 'frcnn':
            # per-image inference — no batched predict for torchvision models
            batch_preds = [frcnn_predict(model, ip, conf=conf) for ip in img_paths]
        else:
            results = model.predict(img_paths, conf=conf, iou=0.45,
                                     imgsz=IMGSZ, verbose=False, device=DEVICE)

        for bi, tgt in enumerate(targets):
            gt_boxes  = tgt['boxes']          # (N,4)  x1y1x2y2
            gt_labels = tgt['labels']         # (N,) 0-indexed

            if model_type == 'frcnn':
                b, s, l = batch_preds[bi]
                pred_boxes  = torch.tensor(b, dtype=torch.float32)
                pred_scores = torch.tensor(s, dtype=torch.float32)
                pred_labels = torch.tensor(l, dtype=torch.int64)
            else:
                res = results[bi]
                pred_boxes  = torch.tensor(res.boxes.xyxy.cpu().numpy(),  dtype=torch.float32)
                pred_scores = torch.tensor(res.boxes.conf.cpu().numpy(),  dtype=torch.float32)
                pred_labels = torch.tensor(res.boxes.cls.cpu().numpy(),   dtype=torch.int64)

            # ── per-image TP/FP/FN per class ──────────────────────────────
            rec = {'img': tgt['img_path']}
            for c in range(NC):
                gt_c  = gt_boxes[gt_labels == c]
                pd_c  = pred_boxes[pred_labels == c]
                sc_c  = pred_scores[pred_labels == c]
                tp, fp, fn = _match_boxes(gt_c, pd_c, sc_c, iou)
                rec[f'tp_{c}'] = tp;  rec[f'fp_{c}'] = fp;  rec[f'fn_{c}'] = fn
                # scores for ROC
                for s, is_tp in zip(sc_c.tolist(), _tp_flags(gt_c, pd_c, iou)):
                    per_class_scores[c].append((s, int(is_tp)))

            rec['tp_all'] = sum(rec[f'tp_{c}'] for c in range(NC))
            rec['fp_all'] = sum(rec[f'fp_{c}'] for c in range(NC))
            rec['fn_all'] = sum(rec[f'fn_{c}'] for c in range(NC))
            records.append(rec)

            # ── torchmetrics format (1-indexed labels) ──────────────────────
            all_preds.append({
                'boxes'  : pred_boxes,
                'scores' : pred_scores,
                'labels' : pred_labels + 1,
            })
            all_targets.append({
                'boxes'  : gt_boxes,
                'labels' : gt_labels + 1,
            })

    return records, all_preds, all_targets, per_class_scores


def _match_boxes(gt, preds, scores, iou_thr):
    """Return (TP, FP, FN) counts for one class one image."""
    if len(gt) == 0:
        return 0, len(preds), 0
    if len(preds) == 0:
        return 0, 0, len(gt)
    order   = scores.argsort(descending=True)
    preds   = preds[order]
    matched = set()
    tp = fp = 0
    for pb in preds:
        ious   = torchvision.ops.box_iou(pb.unsqueeze(0), gt)[0]
        best_i = int(ious.argmax())
        if ious[best_i] >= iou_thr and best_i not in matched:
            tp += 1;  matched.add(best_i)
        else:
            fp += 1
    fn = len(gt) - len(matched)
    return tp, fp, fn


def _tp_flags(gt, preds, iou_thr):
    """Return list of bool — True if that prediction is TP."""
    if len(gt) == 0: return [False]*len(preds)
    if len(preds) == 0: return []
    matched, flags = set(), []
    for pb in preds:
        ious   = torchvision.ops.box_iou(pb.unsqueeze(0), gt)[0]
        best_i = int(ious.argmax())
        if ious[best_i] >= iou_thr and best_i not in matched:
            flags.append(True);  matched.add(best_i)
        else:
            flags.append(False)
    return flags


def aggregate_metrics(records, suffix='all'):
    tp = sum(r[f'tp_{suffix}'] for r in records)
    fp = sum(r[f'fp_{suffix}'] for r in records)
    fn = sum(r[f'fn_{suffix}'] for r in records)
    p  = tp / (tp + fp + 1e-9)
    r  = tp / (tp + fn + 1e-9)
    f1 = 2*p*r / (p + r + 1e-9)
    spec_denom = tp + fp + fn   # used for binary image-level specificity below
    return {'TP': tp, 'FP': fp, 'FN': fn,
            'Precision': p, 'Recall': r, 'F1': f1}


