    if not os.path.exists(weights):
        print(f"⚠️  {tag}: weights not found — skipping")
        continue
    print(f"\n  Evaluating {tag} ({model_type}) ...")

    # ── Per-class P/R/F1 from our own TP/FP/FN counters ──────────────────
    records, all_preds, all_tgts, pc_scores = evaluate_model_on_loader(weights, model_type, test_loader)

    row = {'Model': tag}
    for c, cname in enumerate(CLASS_NAMES):
        m = aggregate_metrics(records, suffix=str(c))
        row[f'P_{cname}']  = round(m['Precision'], 4)
        row[f'R_{cname}']  = round(m['Recall'],    4)
        row[f'F1_{cname}'] = round(m['F1'],        4)

    if model_type == 'frcnn':
        # ADDED — torchvision has no .val(); compute per-class AP50 via
        # torchmetrics from the same all_preds/all_tgts collected above
        # (already 1-indexed, consistent with the YOLO branch below)
        _metric = MeanAveragePrecision(iou_thresholds=[0.5], class_metrics=True)
        _metric.update(all_preds, all_tgts)
        _result = _metric.compute()
        map50_overall = float(_result['map_50'])
        _ap50_pc = _result.get('map_per_class', None)
        if _ap50_pc is not None and hasattr(_ap50_pc, '__len__') and len(_ap50_pc) >= NC:
            for c, cname in enumerate(CLASS_NAMES):
                row[f'mAP50_{cname}'] = round(float(_ap50_pc[c]), 4)
        else:
            for cname in CLASS_NAMES:
                row[f'mAP50_{cname}'] = round(map50_overall, 4)
        row['mAP50_overall'] = round(map50_overall, 4)
    else:
        # ── Per-class AP50 via YOLO .val() — avoids torchmetrics index issues ─
        _eval_model  = YOLO(weights)
        _val_metrics = _eval_model.val(
            data    = DATA_YAML,
            split   = 'test',
            imgsz   = IMGSZ,
            batch   = BATCH,
            device  = DEVICE,
            verbose = False,
        )
        # .box.ap50 is a numpy array of shape (NC,) — one AP@0.50 per class
        try:
            _ap50 = _val_metrics.box.ap50   # ndarray (NC,)
            if _ap50 is not None and hasattr(_ap50, '__len__') and len(_ap50) == NC:
                for c, cname in enumerate(CLASS_NAMES):
                    row[f'mAP50_{cname}'] = round(float(_ap50[c]), 4)
            elif _ap50 is not None and hasattr(_ap50, '__len__') and len(_ap50) > 0:
                # more or fewer classes than expected — fill what we can
                for c, cname in enumerate(CLASS_NAMES):
                    row[f'mAP50_{cname}'] = round(float(_ap50[c]), 4) if len(_ap50) > c else -1
            else:
                # scalar fallback — YOLO only detected 1 class; use overall map50
                for cname in CLASS_NAMES:
                    row[f'mAP50_{cname}'] = round(float(_val_metrics.box.map50), 4)
        except Exception as _e:
            print(f"    ⚠️  per-class AP50 extraction failed ({_e}); using overall map50")
            for cname in CLASS_NAMES:
                row[f'mAP50_{cname}'] = round(float(_val_metrics.box.map50), 4)

        row['mAP50_overall'] = round(float(_val_metrics.box.map50), 4)

    per_class_results.append(row)
    print(f"  {tag} — enamel AP50={row.get('mAP50_enamel-caries','?')}  "
          f"dentin AP50={row.get('mAP50_dentin-caries','?')}")

