print("="*70)

def bootstrap_ci(records, metric_fn, n_boot=N_BOOT, ci=0.95):
    """
    Resample `records` with replacement N_BOOT times.
    metric_fn(records) → float
    Returns (mean, lower, upper)
    """
    np.random.seed(42)
    n      = len(records)
    boots  = []
    for _ in range(n_boot):
        sample = [records[i] for i in np.random.randint(0, n, n)]
        boots.append(metric_fn(sample))
    boots   = np.array(boots)
    alpha   = (1 - ci) / 2
    lower   = np.percentile(boots, alpha * 100)
    upper   = np.percentile(boots, (1 - alpha) * 100)
    return float(np.mean(boots)), float(lower), float(upper)


def f1_fn(recs):
    m = aggregate_metrics(recs)
    return m['F1']

def prec_fn(recs):
    m = aggregate_metrics(recs)
    return m['Precision']

def rec_fn(recs):
    m = aggregate_metrics(recs)
    return m['Recall']


