# CHANGED — added model_type param, dispatch to frcnn_predict per-image
def compute_class_sens_spec_auc(weights_path, model_type, loader, class_idx, conf_sweep=0.25):
    """
    Per-class Sensitivity, Specificity, AUC-ROC.
    Sweeps confidence from 0.01→0.99 for ROC curve.
    Returns sens, spec (at conf_sweep), auc, fpr_arr, tpr_arr
    """
    if model_type == 'frcnn':
        model = load_faster_rcnn(weights_path)
    else:
        model = YOLO(weights_path)

    img_paths = [t['img_path'] for _, t in loader.dataset]

    # Collect GT labels and max-class-score per image
    gt_labels, pred_scores = [], []
    for ip, (_, tgt) in zip(img_paths, loader.dataset):
        gt_c = int((tgt['labels'] == class_idx).sum()) > 0
        gt_labels.append(int(gt_c))

        if model_type == 'frcnn':
            b, s, l = frcnn_predict(model, ip, conf=0.01)
            if len(l) == 0:
                pred_scores.append(0.0)
            else:
                mask = l == class_idx
                pred_scores.append(float(s[mask].max()) if mask.any() else 0.0)
        else:
            res = model.predict(ip, conf=0.01, verbose=False, device=DEVICE)
            boxes = res[0].boxes
            if len(boxes) == 0:
                pred_scores.append(0.0)
            else:
                cls_mask = boxes.cls.cpu().numpy().astype(int) == class_idx
                if cls_mask.any():
                    pred_scores.append(float(boxes.conf.cpu().numpy()[cls_mask].max()))
                else:
                    pred_scores.append(0.0)

    gt_labels   = np.array(gt_labels)
    pred_scores = np.array(pred_scores)

    # Sensitivity / Specificity at fixed threshold
    pred_bin = (pred_scores >= conf_sweep).astype(int)
    tp = int(((gt_labels == 1) & (pred_bin == 1)).sum())
    tn = int(((gt_labels == 0) & (pred_bin == 0)).sum())
    fp = int(((gt_labels == 0) & (pred_bin == 1)).sum())
    fn = int(((gt_labels == 1) & (pred_bin == 0)).sum())
    sens = tp / (tp + fn + 1e-9)
    spec = tn / (tn + fp + 1e-9)

    # AUC — needs both classes present
    if len(np.unique(gt_labels)) > 1:
        auc = roc_auc_score(gt_labels, pred_scores)
        fpr, tpr, _ = roc_curve(gt_labels, pred_scores)
    else:
        auc, fpr, tpr = float('nan'), np.array([0,1]), np.array([0,1])

    return sens, spec, auc, fpr, tpr, gt_labels, pred_scores


