# 8. STEP 5 — McNEMAR'S TEST  (pairwise model comparison)
# ─────────────────────────────────────────────────────────────────────────────
print("\n" + "="*70)
print("STEP 5 — McNEMAR'S TEST  (pairwise statistical significance)")
print("="*70)
print("H₀: two models make errors on the same images (no significant difference)")
print("p < 0.05 → reject H₀ → models differ significantly\n")

# Collect per-image binary correct/incorrect for each model
model_correct = {}   # tag → list[bool]  (length = len(test_ds))

# CHANGED — unpack spec dict
for tag, spec in MODELS_TO_EVAL.items():
    weights, model_type = spec['ckpt'], spec['type']
    if not os.path.exists(weights): continue
    records, _, _, _ = evaluate_model_on_loader(weights, model_type, test_loader)
    # "correct" on an image = at least one TP and no FP and no FN
    correct = [(r['tp_all'] > 0 and r['fp_all'] == 0 and r['fn_all'] == 0)
               for r in records]
    model_correct[tag] = correct

tags = list(model_correct.keys())
mcnemar_rows = []

for i in range(len(tags)):
    for j in range(i+1, len(tags)):
        t1, t2 = tags[i], tags[j]
        a = b = c = d = 0
        for ci, cj in zip(model_correct[t1], model_correct[t2]):
            if     ci and     cj: a += 1   # both correct
            if     ci and not cj: b += 1   # t1 correct, t2 wrong
            if not ci and     cj: c += 1   # t1 wrong,   t2 correct
            if not ci and not cj: d += 1   # both wrong
        # McNemar statistic (with continuity correction)
        n  = b + c
        if n == 0:
            chi2, p = 0.0, 1.0
        else:
            chi2 = (abs(b - c) - 1)**2 / n if n > 0 else 0.0
            from scipy.stats import chi2 as chi2_dist
            p = 1 - chi2_dist.cdf(chi2, df=1)
        mcnemar_rows.append({
            'Model_A': t1, 'Model_B': t2,
            'b (A✓ B✗)': b, 'c (A✗ B✓)': c,
            'McNemar_chi2': round(chi2, 4),
            'p_value': round(p, 6),
            'Significant (p<0.05)': 'YES' if p < 0.05 else 'no',
        })

mcnemar_df = pd.DataFrame(mcnemar_rows)
mcnemar_df.to_csv(os.path.join(STATS_DIR, 'mcnemar_test.csv'), index=False)
print(mcnemar_df[['Model_A','Model_B','McNemar_chi2','p_value','Significant (p<0.05)']].to_string(index=False))

