VAL_IMG_DIR = f'{BASE_DIR}/valid/images'
VAL_LBL_DIR = f'{BASE_DIR}/valid/labels'

WBF_IOU_THR      = 0.50
WBF_SKIP_BOX_THR = 0.001

# ── load_faster_rcnn / frcnn_predict already defined earlier in your
# comprehensive-eval script — skip redefining if so. If this cell errors
# with "already defined", that's fine, ignore it.

def yolo_txt_to_xyxy(label_path, img_w, img_h):
    boxes, labels = [], []
    if os.path.exists(label_path):
        with open(label_path) as f:
            for line in f:
                parts = line.strip().split()
                if len(parts) != 5:
                    continue
                cls, cx, cy, w, h = parts
                cls = int(cls)
                cx, cy, w, h = float(cx), float(cy), float(w), float(h)
                x1 = (cx - w / 2) * img_w
                y1 = (cy - h / 2) * img_h
                x2 = (cx + w / 2) * img_w
                y2 = (cy + h / 2) * img_h
                boxes.append([x1, y1, x2, y2])
                labels.append(cls)
    return np.array(boxes, dtype=np.float32).reshape(-1, 4), np.array(labels, dtype=np.int64)


def get_predictions_and_targets_any(model, model_type, image_dir, label_dir,
                                     conf=CONF_THR, device=DEVICE):
    img_paths = sorted(glob.glob(os.path.join(image_dir, '*.jpg')) +
                        glob.glob(os.path.join(image_dir, '*.png')))
    assert len(img_paths) > 0, f"No images found in {image_dir}"

    cache = []
    for p in img_paths:
        w, h = PILImage.open(p).size
        stem = os.path.splitext(os.path.basename(p))[0]
        lbl_path = os.path.join(label_dir, stem + '.txt')
        gt_boxes, gt_labels = yolo_txt_to_xyxy(lbl_path, w, h)

        if model_type == 'frcnn':
            pred_boxes, pred_scores, pred_labels = frcnn_predict(model, p, conf=conf)
        else:
            res = model.predict(p, conf=conf, device=device, verbose=False)[0]
            if res.boxes is not None and len(res.boxes) > 0:
                pred_boxes  = res.boxes.xyxy.cpu().numpy()
                pred_scores = res.boxes.conf.cpu().numpy()
                pred_labels = res.boxes.cls.cpu().numpy().astype(np.int64)
            else:
                pred_boxes  = np.zeros((0, 4), dtype=np.float32)
                pred_scores = np.zeros((0,), dtype=np.float32)
                pred_labels = np.zeros((0,), dtype=np.int64)

        cache.append({
            'image_path': p, 'width': w, 'height': h,
            'gt_boxes': gt_boxes, 'gt_labels': gt_labels,
            'pred_boxes': pred_boxes, 'pred_scores': pred_scores, 'pred_labels': pred_labels,
        })
    return cache


def compute_map_from_cache(cache, iou_thresholds=(0.5,)):
    metric = MeanAveragePrecision(iou_thresholds=list(iou_thresholds) if len(iou_thresholds) > 1
                                   else [0.5 + 0.05 * i for i in range(10)],
                                   class_metrics=True)
    preds, targets = [], []
    for item in cache:
        preds.append({
            'boxes':  torch.tensor(item['pred_boxes'], dtype=torch.float32),
            'scores': torch.tensor(item['pred_scores'], dtype=torch.float32),
            'labels': torch.tensor(item['pred_labels'], dtype=torch.int64),
        })
        targets.append({
            'boxes':  torch.tensor(item['gt_boxes'], dtype=torch.float32),
            'labels': torch.tensor(item['gt_labels'], dtype=torch.int64),
        })
    metric.update(preds, targets)
    result = metric.compute()
    return {
        'map_50': float(result['map_50']),
        'map': float(result['map']),
        'map_per_class': result.get('map_per_class', None),
    }


def _box_iou_simple(a, b):
    xa1, ya1, xa2, ya2 = a
    xb1, yb1, xb2, yb2 = b
    ix1, iy1 = max(xa1, xb1), max(ya1, yb1)
    ix2, iy2 = min(xa2, xb2), min(ya2, yb2)
    iw, ih = max(0.0, ix2 - ix1), max(0.0, iy2 - iy1)
    inter = iw * ih
    area_a = max(0.0, xa2 - xa1) * max(0.0, ya2 - ya1)
    area_b = max(0.0, xb2 - xb1) * max(0.0, yb2 - yb1)
    union = area_a + area_b - inter
    return inter / union if union > 0 else 0.0


def _greedy_iou_match(pred_boxes, pred_scores, pred_labels, gt_boxes, gt_labels, iou_thr=IOU_THR):
    n_pred, n_gt = len(pred_boxes), len(gt_boxes)
    tp_flags = np.zeros(n_pred, dtype=bool)
    gt_matched = np.zeros(n_gt, dtype=bool)
    order = np.argsort(-pred_scores) if n_pred > 0 else np.array([], dtype=int)
    for i in order:
        cls = pred_labels[i]
        best_iou, best_j = 0.0, -1
        for j in range(n_gt):
            if gt_matched[j] or gt_labels[j] != cls:
                continue
            iou = _box_iou_simple(pred_boxes[i], gt_boxes[j])
            if iou > best_iou:
                best_iou, best_j = iou, j
        if best_iou >= iou_thr and best_j >= 0:
            tp_flags[i] = True
            gt_matched[best_j] = True
    fn = int((~gt_matched).sum())
    return tp_flags, fn


def compute_prf1_from_cache(cache, iou_thr=IOU_THR):
    tp_total = fp_total = fn_total = 0
    for item in cache:
        tp_flags, fn = _greedy_iou_match(
            item['pred_boxes'], item['pred_scores'], item['pred_labels'],
            item['gt_boxes'], item['gt_labels'], iou_thr=iou_thr)
        tp_total += int(tp_flags.sum())
        fp_total += int((~tp_flags).sum())
        fn_total += fn
    precision = tp_total / (tp_total + fp_total + 1e-9)
    recall    = tp_total / (tp_total + fn_total + 1e-9)
    f1        = 2 * precision * recall / (precision + recall + 1e-9)
    return precision, recall, f1


def compute_fpi_from_cache(cache, iou_thr=IOU_THR):
    tp_total = fp_total = fn_total = 0
    for item in cache:
        tp_flags, fn = _greedy_iou_match(
            item['pred_boxes'], item['pred_scores'], item['pred_labels'],
            item['gt_boxes'], item['gt_labels'], iou_thr=iou_thr)
        tp_total += int(tp_flags.sum())
        fp_total += int((~tp_flags).sum())
        fn_total += fn
    n_images = len(cache)
    return {'FPI': fp_total / n_images if n_images else float('nan'),
            'FP': fp_total, 'TP': tp_total, 'FN': fn_total}


def build_validation_caches(models_dict):
    caches_by_model = {}
    map50_by_model = {}
    for name, spec in models_dict.items():
        ckpt, model_type = spec['ckpt'], spec['type']
        if not os.path.exists(ckpt):
            print(f"⚠️  Skipping {name}: checkpoint not found at {ckpt}")
            continue
        print(f"\nRunning {name} ({model_type}) on validation set ...")
        model = load_faster_rcnn(ckpt) if model_type == 'frcnn' else YOLO(ckpt)
        cache = get_predictions_and_targets_any(model, model_type, VAL_IMG_DIR, VAL_LBL_DIR,
                                                 conf=CONF_THR, device=DEVICE)
        caches_by_model[name] = cache
        m = compute_map_from_cache(cache, iou_thresholds=(0.5,))
        map50_by_model[name] = m['map_50']
        print(f"  Validation mAP50={m['map_50']:.4f}")
    return caches_by_model, map50_by_model


def wbf_fuse_predictions(caches, image_idx, img_w, img_h, weights,
                          iou_thr=WBF_IOU_THR, skip_box_thr=WBF_SKIP_BOX_THR):
    boxes_list, scores_list, labels_list = [], [], []
    for cache in caches:
        item = cache[image_idx]
        b = item['pred_boxes'].copy()
        if len(b) > 0:
            b[:, [0, 2]] /= img_w
            b[:, [1, 3]] /= img_h
        boxes_list.append(b.tolist())
        scores_list.append(item['pred_scores'].tolist())
        labels_list.append(item['pred_labels'].tolist())
    fused_boxes, fused_scores, fused_labels = weighted_boxes_fusion(
        boxes_list, scores_list, labels_list,
        weights=weights, iou_thr=iou_thr, skip_box_thr=skip_box_thr)
    if len(fused_boxes) > 0:
        fused_boxes[:, [0, 2]] *= img_w
        fused_boxes[:, [1, 3]] *= img_h
    return fused_boxes, fused_scores, fused_labels


def _fuse_cache_for_subset(active_caches, weights, iou_thr=WBF_IOU_THR, skip_box_thr=WBF_SKIP_BOX_THR):
    n_images = len(active_caches[0])
    fused_cache = []
    for i in range(n_images):
        w, h = active_caches[0][i]['width'], active_caches[0][i]['height']
        fb, fs, fl = wbf_fuse_predictions(active_caches, i, w, h, weights,
                                           iou_thr=iou_thr, skip_box_thr=skip_box_thr)
        fused_cache.append({
            'gt_boxes': active_caches[0][i]['gt_boxes'], 'gt_labels': active_caches[0][i]['gt_labels'],
            'pred_boxes': np.array(fb).reshape(-1, 4), 'pred_scores': np.array(fs),
            'pred_labels': np.array(fl, dtype=np.int64),
        })
    return fused_cache

print("✅ WBF helpers loaded.")

# ─────────────────────────────────────────────────────────────────────────────
# WEIGHTED ENSEMBLE SWEEP — VALIDATION SET, TOP-5 MODELS ONLY, sizes 2..5,
# both weighting strategies (equal / by_map50), all metrics
# ─────────────────────────────────────────────────────────────────────────────

from itertools import combinations

# Build fresh validation caches (no caching layer — guaranteed current)
val_caches_by_model, val_map50_by_model = build_validation_caches(MODELS_TO_EVAL)

print("\nValidation mAP50 ranking (full pool):")
for name, score in sorted(val_map50_by_model.items(), key=lambda x: -x[1]):
    print(f"  {name:14s}: {score:.4f}")

TOP_K = 5
POOL = sorted(val_caches_by_model.keys(), key=lambda n: -val_map50_by_model[n])[:TOP_K]
print(f"\nTop-{TOP_K} pool: {POOL}")

MIN_SIZE, MAX_SIZE = 2, len(POOL)

all_rows = []

# also record solo baselines for reference
for name in POOL:
    m = compute_map_from_cache(val_caches_by_model[name], iou_thresholds=(0.5,))
    p, r, f1 = compute_prf1_from_cache(val_caches_by_model[name], iou_thr=IOU_THR)
    fpi_stats = compute_fpi_from_cache(val_caches_by_model[name], iou_thr=IOU_THR)
    all_rows.append({
        'N_models': 1, 'Combination': name, 'Weighting': 'n/a',
        'mAP50': round(m['map_50'], 4), 'mAP50-95': round(m['map'], 4),
        'Precision': round(p, 4), 'Recall': round(r, 4), 'F1': round(f1, 4),
        'FPI': round(fpi_stats['FPI'], 4),
    })

for k in range(MIN_SIZE, MAX_SIZE + 1):
    for combo in combinations(POOL, k):
        active_caches = [val_caches_by_model[n] for n in combo]

        for strat_name, get_weights in [
            ('equal',    lambda c: [1.0] * len(c)),
            ('by_map50', lambda c: [val_map50_by_model[n] for n in c]),
        ]:
            weights = get_weights(combo)
            fused = _fuse_cache_for_subset(active_caches, weights, iou_thr=WBF_IOU_THR)
            m = compute_map_from_cache(fused, iou_thresholds=(0.5,))
            p, r, f1 = compute_prf1_from_cache(fused, iou_thr=IOU_THR)
            fpi_stats = compute_fpi_from_cache(fused, iou_thr=IOU_THR)

            all_rows.append({
                'N_models': k,
                'Combination': ' + '.join(combo),
                'Weighting': strat_name,
                'mAP50': round(m['map_50'], 4),
                'mAP50-95': round(m['map'], 4),
                'Precision': round(p, 4),
                'Recall': round(r, 4),
                'F1': round(f1, 4),
                'FPI': round(fpi_stats['FPI'], 4),
            })
            print(f"  [{k}-model, {strat_name:9s}] {' + '.join(combo)}: mAP50={m['map_50']:.4f}")

results_df = pd.DataFrame(all_rows)
results_df.to_csv(os.path.join(STATS_DIR, 'weighted_ensemble_sweep_VALIDATION_top5.csv'), index=False)

# ── Print full results, sorted ──
print("\n" + "=" * 110)
print(f"ALL RESULTS — VALIDATION, top-{TOP_K} pool ({POOL})")
print("=" * 110)
print(results_df.sort_values('mAP50', ascending=False).to_string(index=False))

# ── Best combo per size, per weighting strategy ──
print("\n" + "=" * 110)
print("BEST COMBO PER SIZE (both weighting strategies)")
print("=" * 110)
for k in range(1, MAX_SIZE + 1):
    for strat in (['n/a'] if k == 1 else ['equal', 'by_map50']):
        subset = results_df[(results_df['N_models'] == k) & (results_df['Weighting'] == strat)]
        if subset.empty:
            continue
        best = subset.sort_values('mAP50', ascending=False).iloc[0]
        print(f"Size {k} [{strat:9s}] mAP50={best['mAP50']:.4f}  mAP50-95={best['mAP50-95']:.4f}  "
              f"P={best['Precision']:.4f}  R={best['Recall']:.4f}  F1={best['F1']:.4f}  "
              f"FPI={best['FPI']:.4f}  -> {best['Combination']}")

# ── Overall winner ──
overall_best = results_df[results_df['N_models'] > 1].sort_values('mAP50', ascending=False).iloc[0]
print("\n" + "=" * 110)
print(f"🏆 OVERALL BEST ENSEMBLE (any size 2-{MAX_SIZE}, any weighting) — VALIDATION")
print("=" * 110)
print(overall_best.to_string())

print(f"\nSaved to {os.path.join(STATS_DIR, 'weighted_ensemble_sweep_VALIDATION_top5.csv')}")

