def measure_inference_speed(weights_path, model_name, n_warmup=50, n_runs=200):
    """
    Proper GPU latency measurement:
    - Warm up n_warmup times to stabilize CUDA
    - Measure n_runs times with torch.cuda.synchronize()
    - Returns mean ms/image and FPS
    """
    model = YOLO(weights_path)
    model.to(f'cuda:{DEVICE}')

    dummy = torch.zeros(1, 3, IMGSZ, IMGSZ).to(f'cuda:{DEVICE}')

    # Warmup
    for _ in range(n_warmup):
        _ = model.model(dummy)
    torch.cuda.synchronize()

    # Timed runs
    times = []
    for _ in range(n_runs):
        torch.cuda.synchronize()
        t0 = time.perf_counter()
        _ = model.model(dummy)
        torch.cuda.synchronize()
        times.append((time.perf_counter() - t0) * 1000)   # ms

    mean_ms  = float(np.mean(times))
    std_ms   = float(np.std(times))
    fps      = 1000.0 / mean_ms

    print(f"  {model_name:<12}: {mean_ms:.2f} ± {std_ms:.2f} ms/image  |  {fps:.1f} FPS")
    return {'Model': model_name, 'ms_per_image': round(mean_ms, 2),
            'std_ms': round(std_ms, 2), 'FPS': round(fps, 1)}


