# ─────────────────────────────────────────────────────────────────────────────
# STEP B — CALIBRATION CURVES  (reliability diagrams)
# ─────────────────────────────────────────────────────────────────────────────
print("\n" + "="*60)
print("STEP B — CALIBRATION CURVES")
print("="*60)

def collect_confidences_and_correctness(weights_path, test_img_dir, test_lbl_dir,
                                         iou_thresh=0.5, conf_thresh=0.01):
    """
    Run model on test set.
    Returns two lists:
      confs  : predicted confidence scores
      correct: 1 if TP (IoU >= thresh with a GT box of same class), else 0
    """
    import torchvision

    model = YOLO(weights_path)
    img_paths = sorted(
        glob.glob(os.path.join(test_img_dir, '*.jpg')) +
        glob.glob(os.path.join(test_img_dir, '*.png'))
    )

    all_confs, all_correct = [], []

    for img_path in img_paths:
        img = Image.open(img_path).convert('RGB')
        W, H = img.size

        # Ground truth
        lbl_path = os.path.join(test_lbl_dir,
                    os.path.splitext(os.path.basename(img_path))[0] + '.txt')
        gt_boxes, gt_classes = [], []
        if os.path.exists(lbl_path):
            with open(lbl_path) as f:
                for line in f:
                    parts = line.strip().split()
                    if len(parts) < 5: continue
                    cls, cx, cy, bw, bh = map(float, parts[:5])
                    x1 = (cx - bw/2) * W;  y1 = (cy - bh/2) * H
                    x2 = (cx + bw/2) * W;  y2 = (cy + bh/2) * H
                    gt_boxes.append([x1, y1, x2, y2])
                    gt_classes.append(int(cls))

        # Predictions
        results = model.predict(img_path, conf=conf_thresh, iou=0.45,
                                verbose=False, device=DEVICE)
        preds   = results[0].boxes

        if preds is None or len(preds) == 0:
            continue

        pd_boxes   = preds.xyxy.cpu().numpy()
        pd_confs   = preds.conf.cpu().numpy()
        pd_classes = preds.cls.cpu().numpy().astype(int)

        matched_gt = set()
        for pb, pc, pcls in zip(pd_boxes, pd_confs, pd_classes):
            is_correct = 0
            if len(gt_boxes) > 0:
                gt_t = torch.tensor(gt_boxes, dtype=torch.float32)
                pd_t = torch.tensor([pb],     dtype=torch.float32)
                ious = torchvision.ops.box_iou(pd_t, gt_t)[0].numpy()
                for gi in np.argsort(ious)[::-1]:
                    if ious[gi] >= iou_thresh and gi not in matched_gt:
                        if gt_classes[gi] == pcls:
                            is_correct = 1
                            matched_gt.add(gi)
                            break
            all_confs.append(float(pc))
            all_correct.append(is_correct)

    return np.array(all_confs), np.array(all_correct)


def plot_calibration_curve(confs, correct, model_name, ax, color):
    """Plot reliability diagram on given axis."""
    bins = np.linspace(0, 1, 11)
    bin_centers, bin_accs, bin_counts = [], [], []

    for i in range(len(bins) - 1):
        mask = (confs >= bins[i]) & (confs < bins[i+1])
        if mask.sum() > 0:
            bin_centers.append((bins[i] + bins[i+1]) / 2)
            bin_accs.append(correct[mask].mean())
            bin_counts.append(mask.sum())

    bin_centers = np.array(bin_centers)
    bin_accs    = np.array(bin_accs)

    # ECE — Expected Calibration Error
    total = len(confs)
    ece = sum(abs(bin_accs[i] - bin_centers[i]) * bin_counts[i] / total
              for i in range(len(bin_centers)))

    ax.plot([0, 1], [0, 1], 'k--', linewidth=1, label='Perfect calibration')
    ax.bar(bin_centers, bin_accs, width=0.09, alpha=0.6, color=color,
           edgecolor='black', linewidth=0.5, label=f'ECE={ece:.3f}')
    ax.set_xlim(0, 1);  ax.set_ylim(0, 1)
    ax.set_xlabel('Confidence');  ax.set_ylabel('Fraction Positives')
    ax.set_title(model_name, fontweight='bold')
    ax.legend(fontsize=8)
    return ece


# Run calibration for all models
