# Colors for bounding boxes
CLS_COLORS = {
    0: (255, 100, 100),   # dentin-caries  → red
    1: (100, 200, 100),   # enamel-caries  → green
}
GT_COLOR  = (255, 215, 0)   # gold for ground truth

def draw_boxes(img_pil, boxes_xyxy, classes, confs=None, color_map=None, label_prefix=''):
    """Draw bounding boxes on PIL image. Returns new image."""
    draw = ImageDraw.Draw(img_pil.copy())
    result = img_pil.copy()
    draw   = ImageDraw.Draw(result)
    for i, (box, cls) in enumerate(zip(boxes_xyxy, classes)):
        color = color_map.get(int(cls), (200, 200, 200)) if color_map else (200, 200, 200)
        x1, y1, x2, y2 = [int(v) for v in box]
        draw.rectangle([x1, y1, x2, y2], outline=color, width=3)
        label = f"{label_prefix}{CLASS_NAMES[int(cls)]}"
        if confs is not None:
            label += f" {confs[i]:.2f}"
        draw.rectangle([x1, y1-16, x1+len(label)*7, y1], fill=color)
        draw.text((x1+2, y1-15), label, fill=(0, 0, 0))
    return result


def load_gt(lbl_path, W, H):
    """Load YOLO labels → xyxy boxes + classes."""
    gt_boxes, gt_classes = [], []
    if os.path.exists(lbl_path):
        with open(lbl_path) as f:
            for line in f:
                parts = line.strip().split()
                if len(parts) < 5: continue
                cls, cx, cy, bw, bh = map(float, parts[:5])
                x1 = (cx - bw/2) * W;  y1 = (cy - bh/2) * H
                x2 = (cx + bw/2) * W;  y2 = (cy + bh/2) * H
                gt_boxes.append([x1, y1, x2, y2])
                gt_classes.append(int(cls))
    return gt_boxes, gt_classes


def classify_detections(pd_boxes, pd_classes, pd_confs, gt_boxes, gt_classes,
                         iou_thresh=0.5):
    """
    Classify each prediction as TP or FP.
    Returns list of (box, cls, conf, 'TP'/'FP') and list of FN gt indices.
    """
    import torchvision
    results = []
    matched_gt = set()

    for pb, pcls, pc in zip(pd_boxes, pd_classes, pd_confs):
        tp = False
        if len(gt_boxes) > 0:
            gt_t = torch.tensor(gt_boxes, dtype=torch.float32)
            pd_t = torch.tensor([pb],     dtype=torch.float32)
            ious = torchvision.ops.box_iou(pd_t, gt_t)[0].numpy()
            for gi in np.argsort(ious)[::-1]:
                if ious[gi] >= iou_thresh and gi not in matched_gt and gt_classes[gi] == pcls:
                    tp = True
                    matched_gt.add(gi)
                    break
        results.append((pb, int(pcls), float(pc), 'TP' if tp else 'FP'))

    fn_indices = [i for i in range(len(gt_boxes)) if i not in matched_gt]
    return results, fn_indices


def build_qualitative_panel(model_name, weights_path, test_img_dir, test_lbl_dir,
                              n_samples=6, conf=0.25, save_dir=SUPP_DIR):
    """
    For the best model, sample n_samples images and create a panel showing:
    - Top row: GT overlay
    - Bottom row: Prediction overlay (TP=green border, FP=red border, FN=dashed gold)
    """
    model = YOLO(weights_path)
    img_paths = sorted(
        glob.glob(os.path.join(test_img_dir, '*.jpg')) +
        glob.glob(os.path.join(test_img_dir, '*.png'))
    )
    random.seed(42)
    sampled = random.sample(img_paths, min(n_samples, len(img_paths)))

    fig, axes = plt.subplots(2, len(sampled), figsize=(len(sampled)*3.5, 7))

    for col, img_path in enumerate(sampled):
        img = Image.open(img_path).convert('RGB')
        W, H = img.size
        lbl_path = os.path.join(test_lbl_dir,
                    os.path.splitext(os.path.basename(img_path))[0] + '.txt')
        gt_boxes, gt_classes = load_gt(lbl_path, W, H)

        # Run prediction
        results = model.predict(img_path, conf=conf, iou=0.45,
                                verbose=False, device=DEVICE)
        preds   = results[0].boxes
        pd_boxes   = preds.xyxy.cpu().numpy()   if preds is not None else []
        pd_confs   = preds.conf.cpu().numpy()   if preds is not None else []
        pd_classes = preds.cls.cpu().numpy().astype(int) if preds is not None else []

        # Ground truth panel
        gt_img = draw_boxes(img, gt_boxes, gt_classes, color_map={0:(255,100,100),1:(100,200,100)})
        axes[0, col].imshow(gt_img)
        axes[0, col].axis('off')
        if col == 0:
            axes[0, col].set_ylabel('Ground Truth', fontsize=10, fontweight='bold')
        axes[0, col].set_title(f'Image {col+1}', fontsize=9)

        # Prediction panel — color by TP/FP, mark FN
        pred_img = img.copy()
        if len(pd_boxes) > 0:
            det_results, fn_indices = classify_detections(
                pd_boxes, pd_classes, pd_confs, gt_boxes, gt_classes)
            draw = ImageDraw.Draw(pred_img)
            for (pb, pcls, pc, status) in det_results:
                color = (0, 200, 0) if status == 'TP' else (220, 0, 0)
                x1, y1, x2, y2 = [int(v) for v in pb]
                draw.rectangle([x1, y1, x2, y2], outline=color, width=3)
                lbl = f"{CLASS_NAMES[pcls]} {pc:.2f}"
                draw.rectangle([x1, y1-16, x1+len(lbl)*7, y1], fill=color)
                draw.text((x1+2, y1-15), lbl, fill=(255,255,255))
            # Draw FN in dashed gold style (thick orange border)
            for gi in fn_indices:
                x1,y1,x2,y2 = [int(v) for v in gt_boxes[gi]]
                draw.rectangle([x1,y1,x2,y2], outline=(255,165,0), width=4)
                draw.text((x1+2, y1+2), f"FN:{CLASS_NAMES[gt_classes[gi]]}", fill=(255,165,0))

        axes[1, col].imshow(pred_img)
        axes[1, col].axis('off')
        if col == 0:
            axes[1, col].set_ylabel('Predictions', fontsize=10, fontweight='bold')

    # Legend
    tp_patch  = mpatches.Patch(color=(0/255, 200/255, 0/255),   label='TP (correct)')
    fp_patch  = mpatches.Patch(color=(220/255, 0/255, 0/255),   label='FP (false alarm)')
    fn_patch  = mpatches.Patch(color=(255/255, 165/255, 0/255), label='FN (missed)')
    fig.legend(handles=[tp_patch, fp_patch, fn_patch],
               loc='lower center', ncol=3, fontsize=10,
               bbox_to_anchor=(0.5, -0.02))

    fig.suptitle(f'Qualitative Detection Results — {model_name}\n'
                 f'Green=TP  Red=FP  Orange=FN  (conf≥{conf})',
                 fontweight='bold', fontsize=12)
    plt.tight_layout()
    out_path = os.path.join(save_dir, f'figC1_qualitative_{model_name}.png')
    fig.savefig(out_path, dpi=300, bbox_inches='tight')
    plt.close()
    print(f"  {out_path} saved")


# Generate qualitative panel for best two models
for name in ['YOLO11s', 'YOLOv8s']:
    wpath = YOLO_WEIGHTS.get(name, '')
    if os.path.exists(wpath):
        build_qualitative_panel(name, wpath, TEST_IMG, TEST_LBL, n_samples=6)
    else:
        print(f"  {name}: weights not found, skipping qualitative")


# ── Error analysis: count TP/FP/FN across full test set ──────────────────────
def full_test_error_analysis(model_name, weights_path, test_img_dir, test_lbl_dir,
                              conf=0.25, iou_thresh=0.5):
    model = YOLO(weights_path)
    img_paths = sorted(
        glob.glob(os.path.join(test_img_dir, '*.jpg')) +
        glob.glob(os.path.join(test_img_dir, '*.png'))
    )
    stats = {cn: {'TP':0,'FP':0,'FN':0} for cn in CLASS_NAMES}

    for img_path in img_paths:
        img = Image.open(img_path).convert('RGB')
        W, H = img.size
        lbl_path = os.path.join(test_lbl_dir,
                    os.path.splitext(os.path.basename(img_path))[0] + '.txt')
        gt_boxes, gt_classes = load_gt(lbl_path, W, H)

        results = model.predict(img_path, conf=conf, iou=0.45,
                                verbose=False, device=DEVICE)
        preds   = results[0].boxes
        pd_boxes   = preds.xyxy.cpu().numpy()   if preds is not None else []
        pd_confs   = preds.conf.cpu().numpy()   if preds is not None else []
        pd_classes = preds.cls.cpu().numpy().astype(int) if preds is not None else []

        if len(pd_boxes) > 0:
            det_results, fn_indices = classify_detections(
                pd_boxes, pd_classes, pd_confs, gt_boxes, gt_classes, iou_thresh)
            for (pb, pcls, pc, status) in det_results:
                cn = CLASS_NAMES[pcls]
                stats[cn][status] += 1
            for gi in fn_indices:
                cn = CLASS_NAMES[gt_classes[gi]]
                stats[cn]['FN'] += 1
        else:
            for gi in range(len(gt_boxes)):
                cn = CLASS_NAMES[gt_classes[gi]]
                stats[cn]['FN'] += 1

    rows = []
    for cn, s in stats.items():
        tp, fp, fn = s['TP'], s['FP'], s['FN']
        p  = tp/(tp+fp+1e-9)
        r  = tp/(tp+fn+1e-9)
        f1 = 2*p*r/(p+r+1e-9)
        rows.append({'Model':model_name,'Class':cn,
                     'TP':tp,'FP':fp,'FN':fn,
                     'Precision':round(p,4),'Recall':round(r,4),'F1':round(f1,4)})
    return rows


error_rows = []
for name in ['YOLO11s', 'YOLOv8s']:
    wpath = YOLO_WEIGHTS.get(name, '')
    if os.path.exists(wpath):
        print(f"  Error analysis: {name}")
        error_rows.extend(full_test_error_analysis(name, wpath, TEST_IMG, TEST_LBL))

if error_rows:
    err_df = pd.DataFrame(error_rows)
    err_df.to_csv(os.path.join(SUPP_DIR, 'error_analysis_per_class.csv'), index=False)
    print(err_df.to_string(index=False))

    # Figure C2: TP/FP/FN stacked bar per class per model
    fig, axes = plt.subplots(1, 2, figsize=(12, 5))
    for ax, cls_name in zip(axes, CLASS_NAMES):
        sub = err_df[err_df['Class'] == cls_name]
        x   = np.arange(len(sub))
        w   = 0.25
        ax.bar(x - w, sub['TP'], w, label='TP', color='#59a14f', edgecolor='black')
        ax.bar(x,     sub['FP'], w, label='FP', color='#e15759', edgecolor='black')
        ax.bar(x + w, sub['FN'], w, label='FN', color='#f28e2b', edgecolor='black')
        ax.set_xticks(x)
        ax.set_xticklabels(sub['Model'])
        ax.set_title(f'{cls_name}', fontweight='bold')
        ax.set_ylabel('Count')
        ax.legend()
    fig.suptitle('TP / FP / FN per Class — Top Models', fontweight='bold')
    plt.tight_layout()
    fig.savefig(os.path.join(SUPP_DIR, 'figC2_error_analysis.png'), dpi=300, bbox_inches='tight')
    plt.close()
    print("  figC2_error_analysis.png saved")


# ─────────────────────────────────────────────────────────────────────────────
# STEP D — 5-FOLD CV ON YOLO11s  (the Pareto-optimal YOLO11 model)
# ─────────────────────────────────────────────────────────────────────────────
print("\n" + "="*60)
print("STEP D — 5-FOLD CV ON YOLO11s")
print("="*60)

import tempfile
from sklearn.model_selection import KFold

CV_MODEL     = 'yolo11s.pt'
CV_TAG       = 'YOLO11s'
N_FOLDS      = 5
CV_EPOCHS    = 50
CV_BATCH     = 8
CV_PATIENCE  = 15
CV_SAVE_DIR  = os.path.join(RESULTS_DIR, 'StatisticalEval')
os.makedirs(CV_SAVE_DIR, exist_ok=True)

# Collect all train+val images
TRAIN_IMG_DIR = f'{BASE_DIR}/train/images'
TRAIN_LBL_DIR = f'{BASE_DIR}/train/labels'
VAL_IMG_DIR   = f'{BASE_DIR}/valid/images'
VAL_LBL_DIR   = f'{BASE_DIR}/valid/labels'

all_imgs = sorted(
    glob.glob(os.path.join(TRAIN_IMG_DIR, '*.jpg')) +
    glob.glob(os.path.join(TRAIN_IMG_DIR, '*.png')) +
    glob.glob(os.path.join(VAL_IMG_DIR,   '*.jpg')) +
    glob.glob(os.path.join(VAL_IMG_DIR,   '*.png'))
)
print(f"  Total train+val images for CV: {len(all_imgs)}")

# Check if CV already done
cv_cache = os.path.join(CV_SAVE_DIR, f'cv_results_{CV_TAG}.json')
if os.path.exists(cv_cache):
    print(f"  Loading cached CV results from {cv_cache}")
    with open(cv_cache) as f:
        cv_rows = json.load(f)
else:
    kf      = KFold(n_splits=N_FOLDS, shuffle=True, random_state=42)
    cv_rows = []

    for fold_idx, (train_idx, val_idx) in enumerate(kf.split(all_imgs), 1):
        print(f"\n  ── Fold {fold_idx}/{N_FOLDS} ──")
        fold_train = [all_imgs[i] for i in train_idx]
        fold_val   = [all_imgs[i] for i in val_idx]
        print(f"     train={len(fold_train)}  val={len(fold_val)}")

        # Write temporary data.yaml for this fold
        tmp_dir = tempfile.mkdtemp(prefix=f'caries_cv_fold_{fold_idx}_')
        fold_train_img = os.path.join(tmp_dir, 'train', 'images')
        fold_train_lbl = os.path.join(tmp_dir, 'train', 'labels')
        fold_val_img   = os.path.join(tmp_dir, 'val',   'images')
        fold_val_lbl   = os.path.join(tmp_dir, 'val',   'labels')
        for d in [fold_train_img, fold_train_lbl, fold_val_img, fold_val_lbl]:
            os.makedirs(d, exist_ok=True)

        # Symlink images + labels
        def link_files(img_list, img_dst, lbl_src_roots, lbl_dst):
            for ip in img_list:
                bn = os.path.basename(ip)
                dst_img = os.path.join(img_dst, bn)
                if not os.path.exists(dst_img):
                    os.symlink(ip, dst_img)
                stem = os.path.splitext(bn)[0]
                for lbl_root in lbl_src_roots:
                    lp = os.path.join(lbl_root, stem + '.txt')
                    if os.path.exists(lp):
                        dst_lbl = os.path.join(lbl_dst, stem + '.txt')
                        if not os.path.exists(dst_lbl):
                            os.symlink(lp, dst_lbl)
                        break

        link_files(fold_train, fold_train_img, [TRAIN_LBL_DIR, VAL_LBL_DIR], fold_train_lbl)
        link_files(fold_val,   fold_val_img,   [TRAIN_LBL_DIR, VAL_LBL_DIR], fold_val_lbl)

        fold_yaml = os.path.join(tmp_dir, 'data.yaml')
        with open(fold_yaml, 'w') as f:
            yaml.dump({
                'train': fold_train_img,
                'val'  : fold_val_img,
                'test' : TEST_IMG,
                'nc'   : 2,
                'names': CLASS_NAMES,
            }, f, default_flow_style=False)

        # Train
        fold_name = f'CV_fold{fold_idx}_{CV_TAG}'
        model = YOLO(CV_MODEL)
        model.train(
            data     = fold_yaml,
            epochs   = CV_EPOCHS,
            imgsz    = IMGSZ,
            batch    = CV_BATCH,
            workers  = 2,
            patience = CV_PATIENCE,
            device   = DEVICE,
            project  = CV_SAVE_DIR,
            name     = fold_name,
            exist_ok = True,
            plots    = True,
            verbose  = False,
        )

        # Evaluate on held-out test set
        best_w = os.path.join(CV_SAVE_DIR, fold_name, 'weights', 'best.pt')
        eval_m = YOLO(best_w)
        vm = eval_m.val(data=DATA_YAML, split='test',
                        imgsz=IMGSZ, batch=CV_BATCH,
                        device=DEVICE, verbose=False,
                        project=CV_SAVE_DIR,
                        name=f'val_fold{fold_idx}_{CV_TAG}',
                        exist_ok=True)
        box = vm.box
        p   = float(box.mp);  r = float(box.mr)
        m50 = float(box.map50); m95 = float(box.map)
        f1  = 2*p*r/(p+r+1e-9)

        row = {'Fold':fold_idx, 'Precision':round(p,4), 'Recall':round(r,4),
               'F1':round(f1,4), 'mAP50':round(m50,4), 'mAP50-95':round(m95,4)}
        cv_rows.append(row)
        print(f"  Fold {fold_idx} — mAP50={m50:.4f}  F1={f1:.4f}  "
              f"P={p:.4f}  R={r:.4f}")

        # Cleanup temp
        shutil.rmtree(tmp_dir, ignore_errors=True)

    with open(cv_cache, 'w') as f:
        json.dump(cv_rows, f, indent=2)

# ── CV Summary ────────────────────────────────────────────────────────────────
cv_df = pd.DataFrame(cv_rows)
cv_df.to_csv(os.path.join(SUPP_DIR, f'cv_{CV_TAG}.csv'), index=False)

metrics_cv = ['Precision', 'Recall', 'F1', 'mAP50', 'mAP50-95']
cv_summary = {}
print(f"\n  5-Fold CV Summary — {CV_TAG}:")
print(f"  {'Metric':<14} {'Mean':>8}  {'Std':>8}  {'95% CI':>20}")
print(f"  {'-'*54}")
for m in metrics_cv:
    vals  = cv_df[m].values
    mean  = vals.mean();  std = vals.std()
    ci_lo = mean - 1.96*std/np.sqrt(N_FOLDS)
    ci_hi = mean + 1.96*std/np.sqrt(N_FOLDS)
    cv_summary[m] = {'mean':round(mean,4), 'std':round(std,4),
                     'ci_lo':round(ci_lo,4), 'ci_hi':round(ci_hi,4)}
    print(f"  {m:<14} {mean:>8.4f}  {std:>8.4f}  [{ci_lo:.4f} – {ci_hi:.4f}]")

with open(os.path.join(SUPP_DIR, f'cv_summary_{CV_TAG}.json'), 'w') as f:
    json.dump(cv_summary, f, indent=2)

# ── Figure D1: CV fold bar + mean±std ────────────────────────────────────────
fig, axes = plt.subplots(1, 2, figsize=(13, 5))

# mAP50 per fold
ax = axes[0]
fold_labels = [f'Fold {i}' for i in cv_df['Fold']]
bars = ax.bar(fold_labels, cv_df['mAP50'], color='#59a14f',
              edgecolor='black', linewidth=0.6, label='Per-fold mAP50')
mean_map = cv_df['mAP50'].mean()
std_map  = cv_df['mAP50'].std()
ax.axhline(mean_map, color='red', linewidth=1.8, linestyle='--',
           label=f'Mean={mean_map:.4f}')
ax.fill_between([-0.5, N_FOLDS-0.5],
                mean_map-std_map, mean_map+std_map,
                color='red', alpha=0.15, label=f'±1 SD={std_map:.4f}')
for bar, v in zip(bars, cv_df['mAP50']):
    ax.text(bar.get_x()+bar.get_width()/2, v+0.005,
            f'{v:.4f}', ha='center', va='bottom', fontsize=9)
ax.set_ylim(0, 1.05)
ax.set_ylabel('mAP@0.50')
ax.set_title(f'5-Fold CV — {CV_TAG} — mAP50 per Fold', fontweight='bold')
ax.legend(fontsize=9)

# Multi-metric mean±std
ax2 = axes[1]
x = np.arange(len(metrics_cv))
means = [cv_summary[m]['mean'] for m in metrics_cv]
stds  = [cv_summary[m]['std']  for m in metrics_cv]
ax2.bar(x, means, yerr=stds, color='#4e79a7', edgecolor='black',
        linewidth=0.6, capsize=5, error_kw={'linewidth':1.5})
ax2.set_xticks(x)
ax2.set_xticklabels(metrics_cv, rotation=20)
ax2.set_ylabel('Score')
ax2.set_ylim(0, 1.05)
ax2.set_title(f'5-Fold CV — {CV_TAG} — Mean ± Std', fontweight='bold')
for xi, (m, s) in enumerate(zip(means, stds)):
    ax2.text(xi, m+s+0.01, f'{m:.3f}', ha='center', va='bottom', fontsize=9)
ax2.grid(axis='y', linestyle='--', alpha=0.4)

plt.tight_layout()
fig.savefig(os.path.join(SUPP_DIR, f'figD1_cv_{CV_TAG}.png'), dpi=300, bbox_inches='tight')
plt.close()
print(f"  figD1_cv_{CV_TAG}.png saved")


