    ["YOLOv9s",        7.17,     26.7,   0.8425,    0.6369, 0.7254, 0.7525, 0.3519,   5.00],
    ["YOLOv10s",       7.22,     None,   0.7202,    0.7134, 0.7168, 0.7256, 0.3468,   None],
    ["RT-DETR-L",     31.99,    103.4,   0.7973,    0.7286, 0.7614, 0.7756, 0.3689,   5.51],
    ["Faster R-CNN",  43.26,     None,   0.6316,    0.5902, 0.6102, 0.5449, 0.2547,  26.66],
