import matplotlib.pyplot as plt
import matplotlib.font_manager as fm
import numpy as np
import os

# Try to use Arial; fall back gracefully if not found
try:
    fm.findfont('Arial', fallback_to_default=False)
    plt.rcParams['font.family'] = 'Arial'
except Exception:
    print("Arial not found, using DejaVu Sans as fallback")
    plt.rcParams['font.family'] = 'DejaVu Sans'

plt.rcParams['font.size'] = 10
plt.rcParams['savefig.facecolor'] = 'white'

# --- Cell 4: Set output directory (EDIT THIS to your project folder) ---
OUTPUT_DIR = '/content/drive/MyDrive/CR1/figures'   # change if needed
os.makedirs(OUTPUT_DIR, exist_ok=True)

# --- Cell 5: Data ---
configs = [
    "YOLOv11s\nsolo", "YOLOv8s\nsolo", "YOLOv9s\nsolo", "YOLOv10s\nsolo", "YOLOv11m\nsolo",
    "WBF\n(2-model)", "WBF\n(3-model)", "WBF\n(4-model)", "WBF\n(5-model)"
]
map50 = [0.7979, 0.8057, 0.7525, 0.7256, 0.7498, 0.8287, 0.8159, 0.8095, 0.7947]
is_ensemble = [False, False, False, False, False, True, True, True, True]

classes = ["Dentin caries", "Enamel caries"]
class_ap = [0.8338, 0.8235]

# --- Cell 6: Build figure ---
fig, axes = plt.subplots(1, 2, figsize=(11, 4.5), gridspec_kw={'width_ratios': [2.2, 1]})

# Panel A: Ensemble comparison
ax = axes[0]
colors = ['#4C72B0' if not e else '#DD8452' for e in is_ensemble]
x = np.arange(len(configs))
bars = ax.bar(x, map50, color=colors, edgecolor='black', linewidth=0.6, width=0.65)

best_idx = int(np.argmax(map50))
bars[best_idx].set_edgecolor('black')
bars[best_idx].set_linewidth(1.8)

for i, v in enumerate(map50):
    ax.text(i, v + 0.01, f"{v:.4f}", ha='center', va='bottom', fontsize=8)

ax.set_xticks(x)
ax.set_xticklabels(configs, fontsize=8.5)
ax.set_ylabel("mAP50")
ax.set_ylim(0, 0.95)
ax.set_title("A. Single-model vs. WBF ensemble performance", fontsize=10.5, fontweight='bold', loc='left')
ax.spines['top'].set_visible(False)
ax.spines['right'].set_visible(False)

from matplotlib.patches import Patch
legend_elems = [
    Patch(facecolor='#4C72B0', edgecolor='black', label='Single model'),
    Patch(facecolor='#DD8452', edgecolor='black', label='WBF ensemble')
]
ax.legend(handles=legend_elems, loc='lower right', fontsize=8, frameon=False)

best_solo = max([v for v, e in zip(map50, is_ensemble) if not e])
ax.axhline(best_solo, color='gray', linestyle='--', linewidth=0.8, alpha=0.6)

# Panel B: Per-class AP
ax2 = axes[1]
bar_colors = ['#55A868', '#C44E52']
x2 = np.arange(len(classes))
bars2 = ax2.bar(x2, class_ap, color=bar_colors, edgecolor='black', linewidth=0.6, width=0.55)

for i, v in enumerate(class_ap):
    ax2.text(i, v + 0.01, f"{v:.4f}", ha='center', va='bottom', fontsize=8.5)

ax2.set_xticks(x2)
ax2.set_xticklabels(classes, fontsize=9)
ax2.set_ylabel("AP@0.50")
ax2.set_ylim(0, 0.95)
ax2.set_title("B. Per-class AP (best model)", fontsize=10.5, fontweight='bold', loc='left')
ax2.spines['top'].set_visible(False)
ax2.spines['right'].set_visible(False)

plt.tight_layout()

# --- Cell 7: Save (PNG for editing, JPG for Karger submission spec) ---
