import pandas as pd
from scipy import stats
import numpy as np

# --- Fold-wise results (from cv_results.json / cv_results_YOLO11s.json) ---
yolov8s = pd.DataFrame([
    {"Fold": 1, "Precision": 0.7867, "Recall": 0.7016, "F1": 0.7417, "mAP50": 0.8054, "mAP50-95": 0.4107},
    {"Fold": 2, "Precision": 0.7183, "Recall": 0.7127, "F1": 0.7155, "mAP50": 0.7410, "mAP50-95": 0.3717},
    {"Fold": 3, "Precision": 0.7173, "Recall": 0.7006, "F1": 0.7089, "mAP50": 0.7306, "mAP50-95": 0.3711},
    {"Fold": 4, "Precision": 0.7379, "Recall": 0.7243, "F1": 0.7311, "mAP50": 0.7608, "mAP50-95": 0.3887},
    {"Fold": 5, "Precision": 0.7957, "Recall": 0.6810, "F1": 0.7339, "mAP50": 0.7508, "mAP50-95": 0.3902},
])

yolo11s = pd.DataFrame([
    {"Fold": 1, "Precision": 0.7352, "Recall": 0.6977, "F1": 0.7159, "mAP50": 0.7475, "mAP50-95": 0.3793},
    {"Fold": 2, "Precision": 0.7990, "Recall": 0.6569, "F1": 0.7210, "mAP50": 0.7333, "mAP50-95": 0.3582},
    {"Fold": 3, "Precision": 0.8093, "Recall": 0.6418, "F1": 0.7159, "mAP50": 0.7650, "mAP50-95": 0.3878},
    {"Fold": 4, "Precision": 0.7199, "Recall": 0.7386, "F1": 0.7292, "mAP50": 0.7353, "mAP50-95": 0.3673},
    {"Fold": 5, "Precision": 0.6916, "Recall": 0.7047, "F1": 0.6981, "mAP50": 0.7050, "mAP50-95": 0.3521},
])

metrics = ["Precision", "Recall", "F1", "mAP50", "mAP50-95"]

# --- Run paired Wilcoxon signed-rank test per metric ---
rows = []
for m in metrics:
    v8 = yolov8s[m].values
    v11 = yolo11s[m].values
    diff = v8 - v11

    # exact method is appropriate given small n (n=5); falls back to
    # normal approximation automatically if ties/zeros make exact infeasible
    try:
        w_stat, p_val = stats.wilcoxon(v8, v11, method="exact")
    except Exception:
        w_stat, p_val = stats.wilcoxon(v8, v11)

    rows.append({
        "Metric": m,
        "YOLOv8s_mean": round(v8.mean(), 4),
        "YOLO11s_mean": round(v11.mean(), 4),
        "Mean_diff": round(diff.mean(), 4),
        "W_statistic": w_stat,
        "p_value": round(p_val, 4),
        "Significant_(a=0.05)": "Yes" if p_val < 0.05 else "No",
    })

results_df = pd.DataFrame(rows)
print(results_df.to_string(index=False))

# --- Save for manuscript / supplementary table ---
results_df.to_csv("wilcoxon_yolo11s_vs_yolov8s.csv", index=False)
print("\nSaved: wilcoxon_yolo11s_vs_yolov8s.csv")

# --- Per-fold differences (for transparency / supplementary material) ---
print("\nPer-fold differences (YOLOv8s - YOLO11s):")
for m in metrics:
    diff = yolov8s[m].values - yolo11s[m].values
    print(f"  {m:<10}: {[round(d, 4) for d in diff]}")

import os
import glob
import difflib
import numpy as np
import cv2
import matplotlib.pyplot as plt
from ensemble_boxes import weighted_boxes_fusion

# ─────────────────────────────────────────────────────────────────────────────
# CONFIG
# ─────────────────────────────────────────────────────────────────────────────
CONF_VIS_THRESH = 0.25
SAVE_PATH = './wbf_outputs/prediction_result.png'

CLASS_COLORS = {
    0: (0, 140, 255),   # dentin-caries  -> orange  (BGR)
    1: (255, 0, 255),   # enamel-caries  -> magenta (BGR)
}
DEFAULT_COLOR = (0, 255, 0)

os.makedirs(os.path.dirname(SAVE_PATH), exist_ok=True)


# ─────────────────────────────────────────────────────────────────────────────
# HELPERS
# ─────────────────────────────────────────────────────────────────────────────
def resolve_image_path(image_dir, image_name_or_path):
    """Find the image the user typed — as a full path, a bare filename in
    image_dir, or a filename missing its extension. Suggests close matches
    on failure instead of just crashing."""
    if os.path.exists(image_name_or_path):
        return image_name_or_path

    candidate = os.path.join(image_dir, image_name_or_path)
    if os.path.exists(candidate):
        return candidate

    base, ext = os.path.splitext(image_name_or_path)
    if not ext:
        for try_ext in ('.jpg', '.jpeg', '.png'):
            candidate = os.path.join(image_dir, base + try_ext)
            if os.path.exists(candidate):
                return candidate

    all_files = [os.path.basename(p) for p in
                 glob.glob(os.path.join(image_dir, '*.jpg')) +
                 glob.glob(os.path.join(image_dir, '*.jpeg')) +
                 glob.glob(os.path.join(image_dir, '*.png'))]
    close = difflib.get_close_matches(os.path.basename(image_name_or_path), all_files, n=5, cutoff=0.4)
    hint = f"\nDid you mean one of: {close}" if close else \
           f"\nFirst few available images: {all_files[:5]}"
    raise FileNotFoundError(f"Could not find '{image_name_or_path}' in '{image_dir}'.{hint}")


def upload_image_colab():
    """Opens a Colab file-picker dialog and returns the path to the uploaded file."""
    from google.colab import files
    uploaded = files.upload()
    fname = list(uploaded.keys())[0]
    return os.path.abspath(fname)


def load_yolo_labels(label_path, img_w, img_h):
    if not os.path.exists(label_path):
        return np.zeros((0, 5))
    boxes = []
    with open(label_path) as f:
        for line in f:
            parts = line.strip().split()
            if len(parts) < 5:
                continue
            cls, x_c, y_c, w, h = map(float, parts[:5])
            x1 = (x_c - w / 2) * img_w
            y1 = (y_c - h / 2) * img_h
            x2 = (x_c + w / 2) * img_w
            y2 = (y_c + h / 2) * img_h
            boxes.append([cls, x1, y1, x2, y2])
    return np.array(boxes) if boxes else np.zeros((0, 5))


def draw_boxes(img, boxes, labels, scores, class_names, show_score=True):
    out = img.copy()
    for box, label, score in zip(boxes, labels, scores):
        x1, y1, x2, y2 = map(int, box)
        cls_idx = int(label)
        color = CLASS_COLORS.get(cls_idx, DEFAULT_COLOR)
        cv2.rectangle(out, (x1, y1), (x2, y2), color, 3)
        cname = class_names[cls_idx]
        caption = f"{cname}: {score:.2f}" if show_score else cname
        (tw, th), _ = cv2.getTextSize(caption, cv2.FONT_HERSHEY_SIMPLEX, 0.5, 2)
        ty = max(y1 - 10, th + 5)
        cv2.rectangle(out, (x1, ty - th - 4), (x1 + tw + 4, ty + 4), color, -1)
        cv2.putText(out, caption, (x1 + 2, ty), cv2.FONT_HERSHEY_SIMPLEX,
                    0.5, (255, 255, 255), 2)
    return out


def run_single_model(loaded_model, img_path, img_w, img_h, conf_thresh):
    results = loaded_model['model'].predict(
        img_path, imgsz=loaded_model['imgsz'], conf=conf_thresh, verbose=False
    )
    r = results[0]
    if r.boxes is None or len(r.boxes) == 0:
        return [], [], []
    xyxy = r.boxes.xyxy.cpu().numpy()
    conf = r.boxes.conf.cpu().numpy()
    cls  = r.boxes.cls.cpu().numpy().astype(int)
    norm_boxes = xyxy.copy()
    norm_boxes[:, [0, 2]] /= img_w
    norm_boxes[:, [1, 3]] /= img_h
    norm_boxes = np.clip(norm_boxes, 0, 1)
    return norm_boxes.tolist(), conf.tolist(), cls.tolist()


# ─────────────────────────────────────────────────────────────────────────────
# CORE: run prediction on one chosen image
# ─────────────────────────────────────────────────────────────────────────────
def predict_on_image(img_path, model_pool, class_names, best_hyperparams,
                      label_dir=None, conf_thresh=0.15,
                      conf_vis_thresh=CONF_VIS_THRESH, save_path=SAVE_PATH):
    img_base = os.path.splitext(os.path.basename(img_path))[0]
    img = cv2.imread(img_path)
    if img is None:
        raise ValueError(f"Could not read image at '{img_path}' — is it a valid image file?")
    h, w = img.shape[:2]

    # Run each model + fuse with WBF using the tuned hyperparameters
    boxes_list, scores_list, labels_list = [], [], []
    for m_name, m_cfg in model_pool.items():
        b, s, l = run_single_model(m_cfg, img_path, w, h, conf_thresh)
        boxes_list.append(b)
        scores_list.append(s)
        labels_list.append(l)

    fused_boxes, fused_scores, fused_labels = weighted_boxes_fusion(
        boxes_list, scores_list, labels_list,
        weights=best_hyperparams['weights'],
        iou_thr=best_hyperparams['iou_thr'],
        skip_box_thr=0.0001,
    )

    if len(fused_boxes) > 0:
        fused_boxes = np.array(fused_boxes)
        fused_boxes[:, [0, 2]] *= w
        fused_boxes[:, [1, 3]] *= h

    keep_idx = [i for i, s in enumerate(fused_scores) if s >= conf_vis_thresh]
    pred_boxes  = [fused_boxes[i] for i in keep_idx] if len(fused_boxes) else []
    pred_labels = [fused_labels[i] for i in keep_idx]
    pred_scores = [fused_scores[i] for i in keep_idx]

    pred_panel = draw_boxes(img, pred_boxes, pred_labels, pred_scores,
                             class_names, show_score=True)
    orig_panel = img.copy()

    # Optional ground truth, only if a matching label file exists
    gt_panel, n_gt = None, None
    if label_dir:
        label_path = os.path.join(label_dir, f'{img_base}.txt')
        if os.path.exists(label_path):
            gt_raw = load_yolo_labels(label_path, w, h)
            gt_labels = gt_raw[:, 0].tolist() if len(gt_raw) else []
            gt_boxes  = gt_raw[:, 1:5].tolist() if len(gt_raw) else []
            gt_scores = [1.0] * len(gt_boxes)
            gt_panel = draw_boxes(img, gt_boxes, gt_labels, gt_scores,
                                   class_names, show_score=False)
            n_gt = len(gt_boxes)

    # Build the figure: 2 panels if no GT available, 3 if it is
    if gt_panel is not None:
        panels = [orig_panel, gt_panel, pred_panel]
        titles = ['Original', f'Ground Truth ({n_gt} lesions)',
                  f'WBF Ensemble Prediction ({len(pred_boxes)} detections)']
    else:
        panels = [orig_panel, pred_panel]
        titles = ['Original', f'WBF Ensemble Prediction ({len(pred_boxes)} detections)']

    fig, axes = plt.subplots(1, len(panels), figsize=(6 * len(panels), 6))
    if len(panels) == 1:
        axes = [axes]
    for ax, panel, title in zip(axes, panels, titles):
        ax.imshow(cv2.cvtColor(panel, cv2.COLOR_BGR2RGB))
        ax.set_title(title, fontsize=13, fontweight='bold')
        ax.axis('off')

    fig.suptitle(f'Image: {img_base}', fontsize=11, y=1.02)
    plt.tight_layout()
    fig.savefig(save_path, dpi=300, bbox_inches='tight')
    plt.show()
    print(f"\nSaved result to {save_path}")

    # Print a readable summary of what was detected
    if pred_boxes:
        print(f"\nDetections ({len(pred_boxes)}):")
        for box, label, score in zip(pred_boxes, pred_labels, pred_scores):
            print(f"  {class_names[int(label)]:15s}  conf={score:.2f}  box={[round(v,1) for v in box]}")
    else:
        print("\nNo lesions detected above the confidence threshold.")

    return img_base, pred_boxes, pred_labels, pred_scores


# ─────────────────────────────────────────────────────────────────────────────
# RUN — asks how you want to select the image
# ─────────────────────────────────────────────────────────────────────────────
if __name__ == '__main__':
    print("How do you want to select the image?")
    print("  [1] Type a filename already in the test folder")
    print("  [2] Type/paste a full path to any image on disk")
    print("  [3] Upload a new image (Colab file picker)")
    choice = input("Choice (1/2/3): ").strip()

    if choice == '3':
        img_path = upload_image_colab()
        label_dir_to_use = None   # a freshly uploaded image has no GT labels
    elif choice == '2':
        img_path = input("Full path to image: ").strip()
        label_dir_to_use = TEST_LABELS_DIR   # will simply be skipped if no match
    else:
        fname = input("Filename in test folder (e.g. IMG_0231.jpg or IMG_0231): ").strip()
        img_path = resolve_image_path(TEST_IMAGES_DIR, fname)
        label_dir_to_use = TEST_LABELS_DIR

    predict_on_image(
        img_path=img_path,
        model_pool=loaded_pool,
        class_names=CLASS_NAMES,
        best_hyperparams=best_hyperparams,
        label_dir=label_dir_to_use,
    )

import os
import glob
import difflib
import numpy as np
import cv2
import matplotlib.pyplot as plt
from ensemble_boxes import weighted_boxes_fusion

# ─────────────────────────────────────────────────────────────────────────────
# CONFIG
# ─────────────────────────────────────────────────────────────────────────────
CONF_VIS_THRESH = 0.25
SAVE_PATH = './wbf_outputs/prediction_result.png'

CLASS_COLORS = {
    0: (0, 140, 255),   # dentin-caries  -> orange  (BGR)
    1: (255, 0, 255),   # enamel-caries  -> magenta (BGR)
}
DEFAULT_COLOR = (0, 255, 0)

os.makedirs(os.path.dirname(SAVE_PATH), exist_ok=True)


# ─────────────────────────────────────────────────────────────────────────────
# HELPERS
# ─────────────────────────────────────────────────────────────────────────────
def resolve_image_path(image_dir, image_name_or_path):
    """Find the image the user typed — as a full path, a bare filename in
    image_dir, or a filename missing its extension. Suggests close matches
    on failure instead of just crashing."""
    if os.path.exists(image_name_or_path):
        return image_name_or_path

    candidate = os.path.join(image_dir, image_name_or_path)
    if os.path.exists(candidate):
        return candidate

    base, ext = os.path.splitext(image_name_or_path)
    if not ext:
        for try_ext in ('.jpg', '.jpeg', '.png'):
            candidate = os.path.join(image_dir, base + try_ext)
            if os.path.exists(candidate):
                return candidate

    all_files = [os.path.basename(p) for p in
                 glob.glob(os.path.join(image_dir, '*.jpg')) +
                 glob.glob(os.path.join(image_dir, '*.jpeg')) +
                 glob.glob(os.path.join(image_dir, '*.png'))]
    close = difflib.get_close_matches(os.path.basename(image_name_or_path), all_files, n=5, cutoff=0.4)
    hint = f"\nDid you mean one of: {close}" if close else \
           f"\nFirst few available images: {all_files[:5]}"
    raise FileNotFoundError(f"Could not find '{image_name_or_path}' in '{image_dir}'.{hint}")


def upload_image_colab():
    """Opens a Colab file-picker dialog and returns the path to the uploaded file."""
    from google.colab import files
    uploaded = files.upload()
    fname = list(uploaded.keys())[0]
    return os.path.abspath(fname)


def load_yolo_labels(label_path, img_w, img_h):
    if not os.path.exists(label_path):
        return np.zeros((0, 5))
    boxes = []
    with open(label_path) as f:
        for line in f:
            parts = line.strip().split()
            if len(parts) < 5:
                continue
            cls, x_c, y_c, w, h = map(float, parts[:5])
            x1 = (x_c - w / 2) * img_w
            y1 = (y_c - h / 2) * img_h
            x2 = (x_c + w / 2) * img_w
            y2 = (y_c + h / 2) * img_h
            boxes.append([cls, x1, y1, x2, y2])
    return np.array(boxes) if boxes else np.zeros((0, 5))


def draw_boxes(img, boxes, labels, scores, class_names, show_score=True):
    out = img.copy()
    for box, label, score in zip(boxes, labels, scores):
        x1, y1, x2, y2 = map(int, box)
        cls_idx = int(label)
        color = CLASS_COLORS.get(cls_idx, DEFAULT_COLOR)
        cv2.rectangle(out, (x1, y1), (x2, y2), color, 3)
        cname = class_names[cls_idx]
        caption = f"{cname}: {score:.2f}" if show_score else cname
        (tw, th), _ = cv2.getTextSize(caption, cv2.FONT_HERSHEY_SIMPLEX, 0.5, 2)
        ty = max(y1 - 10, th + 5)
        cv2.rectangle(out, (x1, ty - th - 4), (x1 + tw + 4, ty + 4), color, -1)
        cv2.putText(out, caption, (x1 + 2, ty), cv2.FONT_HERSHEY_SIMPLEX,
                    0.5, (255, 255, 255), 2)
    return out


def run_single_model(loaded_model, img_path, img_w, img_h, conf_thresh):
    results = loaded_model['model'].predict(
        img_path, imgsz=loaded_model['imgsz'], conf=conf_thresh, verbose=False
    )
    r = results[0]
    if r.boxes is None or len(r.boxes) == 0:
        return [], [], []
    xyxy = r.boxes.xyxy.cpu().numpy()
    conf = r.boxes.conf.cpu().numpy()
    cls  = r.boxes.cls.cpu().numpy().astype(int)
    norm_boxes = xyxy.copy()
    norm_boxes[:, [0, 2]] /= img_w
    norm_boxes[:, [1, 3]] /= img_h
    norm_boxes = np.clip(norm_boxes, 0, 1)
    return norm_boxes.tolist(), conf.tolist(), cls.tolist()


# ─────────────────────────────────────────────────────────────────────────────
# CORE: run prediction on one chosen image
# ─────────────────────────────────────────────────────────────────────────────
def predict_on_image(img_path, model_pool, class_names, best_hyperparams,
                      label_dir=None, conf_thresh=0.15,
                      conf_vis_thresh=CONF_VIS_THRESH, save_path=SAVE_PATH):
    img_base = os.path.splitext(os.path.basename(img_path))[0]
    img = cv2.imread(img_path)
    if img is None:
        raise ValueError(f"Could not read image at '{img_path}' — is it a valid image file?")
    h, w = img.shape[:2]

    # Run each model + fuse with WBF using the tuned hyperparameters
    boxes_list, scores_list, labels_list = [], [], []
    for m_name, m_cfg in model_pool.items():
        b, s, l = run_single_model(m_cfg, img_path, w, h, conf_thresh)
        boxes_list.append(b)
        scores_list.append(s)
        labels_list.append(l)

    fused_boxes, fused_scores, fused_labels = weighted_boxes_fusion(
        boxes_list, scores_list, labels_list,
        weights=best_hyperparams['weights'],
        iou_thr=best_hyperparams['iou_thr'],
        skip_box_thr=0.0001,
    )

    if len(fused_boxes) > 0:
        fused_boxes = np.array(fused_boxes)
        fused_boxes[:, [0, 2]] *= w
        fused_boxes[:, [1, 3]] *= h

    keep_idx = [i for i, s in enumerate(fused_scores) if s >= conf_vis_thresh]
    pred_boxes  = [fused_boxes[i] for i in keep_idx] if len(fused_boxes) else []
    pred_labels = [fused_labels[i] for i in keep_idx]
    pred_scores = [fused_scores[i] for i in keep_idx]

    pred_panel = draw_boxes(img, pred_boxes, pred_labels, pred_scores,
                             class_names, show_score=True)
    orig_panel = img.copy()

    # Optional ground truth, only if a matching label file exists
    gt_panel, n_gt = None, None
    if label_dir:
        label_path = os.path.join(label_dir, f'{img_base}.txt')
        if os.path.exists(label_path):
            gt_raw = load_yolo_labels(label_path, w, h)
            gt_labels = gt_raw[:, 0].tolist() if len(gt_raw) else []
            gt_boxes  = gt_raw[:, 1:5].tolist() if len(gt_raw) else []
            gt_scores = [1.0] * len(gt_boxes)
            gt_panel = draw_boxes(img, gt_boxes, gt_labels, gt_scores,
                                   class_names, show_score=False)
            n_gt = len(gt_boxes)

    # Build the figure: 2 panels if no GT available, 3 if it is
    if gt_panel is not None:
        panels = [orig_panel, gt_panel, pred_panel]
        titles = ['Original', f'Ground Truth ({n_gt} lesions)',
                  f'WBF Ensemble Prediction ({len(pred_boxes)} detections)']
    else:
        panels = [orig_panel, pred_panel]
        titles = ['Original', f'WBF Ensemble Prediction ({len(pred_boxes)} detections)']

    fig, axes = plt.subplots(1, len(panels), figsize=(6 * len(panels), 6))
    if len(panels) == 1:
        axes = [axes]
    for ax, panel, title in zip(axes, panels, titles):
        ax.imshow(cv2.cvtColor(panel, cv2.COLOR_BGR2RGB))
        ax.set_title(title, fontsize=13, fontweight='bold')
        ax.axis('off')

    fig.suptitle(f'Image: {img_base}', fontsize=11, y=1.02)
    plt.tight_layout()
    fig.savefig(save_path, dpi=300, bbox_inches='tight')
    plt.show()
    print(f"\nSaved result to {save_path}")

    # Print a readable summary of what was detected
    if pred_boxes:
        print(f"\nDetections ({len(pred_boxes)}):")
        for box, label, score in zip(pred_boxes, pred_labels, pred_scores):
            print(f"  {class_names[int(label)]:15s}  conf={score:.2f}  box={[round(v,1) for v in box]}")
    else:
        print("\nNo lesions detected above the confidence threshold.")

    return img_base, pred_boxes, pred_labels, pred_scores


# ─────────────────────────────────────────────────────────────────────────────
# RUN — asks how you want to select the image
# ─────────────────────────────────────────────────────────────────────────────
if __name__ == '__main__':
    print("How do you want to select the image?")
    print("  [1] Type a filename already in the test folder")
    print("  [2] Type/paste a full path to any image on disk")
    print("  [3] Upload a new image (Colab file picker)")
    choice = input("Choice (1/2/3): ").strip()

    if choice == '3':
        img_path = upload_image_colab()
        label_dir_to_use = None   # a freshly uploaded image has no GT labels
    elif choice == '2':
        img_path = input("Full path to image: ").strip()
