# ─────────────────────────────────────────────────────────────────────────────
# 3. SHARED HELPERS
# ─────────────────────────────────────────────────────────────────────────────
def load_yolo_labels(label_path, img_w, img_h):
    if not os.path.exists(label_path):
        return np.zeros((0, 5))
    boxes = []
    with open(label_path) as f:
        for line in f:
            parts = line.strip().split()
            if len(parts) < 5:
                continue
            cls, x_c, y_c, w, h = map(float, parts[:5])
            x1 = (x_c - w / 2) * img_w
            y1 = (y_c - h / 2) * img_h
            x2 = (x_c + w / 2) * img_w
            y2 = (y_c + h / 2) * img_h
            boxes.append([cls, x1, y1, x2, y2])
    return np.array(boxes) if boxes else np.zeros((0, 5))


def calculate_iou(boxA, boxB):
    xA, yA = max(boxA[0], boxB[0]), max(boxA[1], boxB[1])
    xB, yB = min(boxA[2], boxB[2]), min(boxA[3], boxB[3])
    interArea = max(0, xB - xA) * max(0, yB - yA)
    boxAArea = (boxA[2] - boxA[0]) * (boxA[3] - boxA[1])
    boxBArea = (boxB[2] - boxB[0]) * (boxB[3] - boxB[1])
    return interArea / float(boxAArea + boxBArea - interArea + 1e-6)


def compute_ap(recalls, precisions):
    recalls = np.concatenate(([0.0], recalls, [1.0]))
    precisions = np.concatenate(([0.0], precisions, [0.0]))
    for i in range(len(precisions) - 2, -1, -1):
        precisions[i] = max(precisions[i], precisions[i + 1])
    idx = np.where(recalls[1:] != recalls[:-1])[0]
    return np.sum((recalls[idx + 1] - recalls[idx]) * precisions[idx + 1])


# ---- Per-architecture inference adapters -----------------------------------
def _infer_yolo_like(entry, img_path, img_w, img_h, conf_thresh):
    results = entry['model'].predict(img_path, imgsz=entry['imgsz'], conf=conf_thresh, verbose=False)
    r = results[0]
    if r.boxes is None or len(r.boxes) == 0:
        return [], [], []
    xyxy = r.boxes.xyxy.cpu().numpy()
    conf = r.boxes.conf.cpu().numpy()
    cls  = r.boxes.cls.cpu().numpy().astype(int)
    norm_boxes = xyxy.copy()
    norm_boxes[:, [0, 2]] /= img_w
    norm_boxes[:, [1, 3]] /= img_h
    norm_boxes = np.clip(norm_boxes, 0, 1)
    return norm_boxes.tolist(), conf.tolist(), cls.tolist()


def _infer_frcnn(entry, img_path, img_w, img_h, conf_thresh):  # ADDED
    """torchvision Faster R-CNN adapter — returns the same
    (norm_boxes, scores, labels) shape as _infer_yolo_like so WBF and the
    rest of the pipeline treat it identically. Runs its own PIL load since
    the cv2 image already read in build_prediction_cache isn't passed
    through (only used there for width/height)."""
    img = PILImage.open(img_path).convert('RGB')
    tensor = TF.to_tensor(img).to(TORCH_DEV)
    with torch.no_grad():
        out = entry['model']([tensor])[0]
    boxes  = out['boxes'].cpu().numpy()
    scores = out['scores'].cpu().numpy()
    labels = out['labels'].cpu().numpy().astype(int) - 1   # torchvision 1-indexed (0=bg) -> 0-indexed

    keep = scores >= conf_thresh
    boxes, scores, labels = boxes[keep], scores[keep], labels[keep]
    if len(boxes) == 0:
        return [], [], []

    norm_boxes = boxes.copy()
    norm_boxes[:, [0, 2]] /= img_w
    norm_boxes[:, [1, 3]] /= img_h
    norm_boxes = np.clip(norm_boxes, 0, 1)
    return norm_boxes.tolist(), scores.tolist(), labels.tolist()


def run_single_model(model_name, img_path, img_w, img_h, conf_thresh=CONF_THRESH):
    entry = loaded_pool[model_name]
    if entry['type'] in ('yolo', 'rtdetr'):
        return _infer_yolo_like(entry, img_path, img_w, img_h, conf_thresh)
    if entry['type'] == 'frcnn':  # ADDED
        return _infer_frcnn(entry, img_path, img_w, img_h, conf_thresh)
    raise ValueError(f"Unknown model type for {model_name}")


# ---- Cache build + WBF/AP scoring against a cache ---------------------------
def build_prediction_cache(model_names, images_dir, cache_tag):
    """Runs each model once over every image in images_dir and caches
    (norm_boxes, scores, labels, img_w, img_h) per image to a pickle file
    on disk, so combination search never re-invokes model.predict()."""
    image_paths = sorted(
        glob.glob(os.path.join(images_dir, '*.jpg')) +
        glob.glob(os.path.join(images_dir, '*.png'))
    )
    assert len(image_paths) > 0, f"No images found in {images_dir}"

    cache = {}
    for m_name in model_names:
        cache_path = os.path.join(CACHE_DIR, f'{cache_tag}__{m_name}.pkl')
        if os.path.exists(cache_path):
            with open(cache_path, 'rb') as f:
                cache[m_name] = pickle.load(f)
            print(f"  Loaded cached predictions: {m_name} ({len(cache[m_name])} images)")
            continue
        print(f"  Running inference once for {m_name} over {len(image_paths)} images...")
        per_image = {}
        for img_path in image_paths:
            img = cv2.imread(img_path)
            h, w = img.shape[:2]
            img_base = os.path.splitext(os.path.basename(img_path))[0]
            b, s, l = run_single_model(m_name, img_path, w, h)
            per_image[img_base] = {'boxes': b, 'scores': s, 'labels': l, 'w': w, 'h': h}
        with open(cache_path, 'wb') as f:
            pickle.dump(per_image, f)
        cache[m_name] = per_image
    return cache, [os.path.splitext(os.path.basename(p))[0] for p in image_paths]


def score_combo_from_cache(model_list, weights, iou_thr, cache, image_bases, labels_dir):
    class_detections = {c: [] for c in range(NUM_CLASSES)}
    class_gt_counts  = {c: 0 for c in range(NUM_CLASSES)}

    for img_base in image_bases:
        w = cache[model_list[0]][img_base]['w']
        h = cache[model_list[0]][img_base]['h']
        label_path = os.path.join(labels_dir, f'{img_base}.txt')
        gt_boxes = load_yolo_labels(label_path, w, h)
        for gt in gt_boxes:
            class_gt_counts[int(gt[0])] += 1

        boxes_list, scores_list, labels_list = [], [], []
        for m_name in model_list:
            entry = cache[m_name][img_base]
            boxes_list.append(entry['boxes'])
            scores_list.append(entry['scores'])
            labels_list.append(entry['labels'])

        fused_boxes, fused_scores, fused_labels = weighted_boxes_fusion(
            boxes_list, scores_list, labels_list,
            weights=weights, iou_thr=iou_thr, skip_box_thr=0.0001
        )

        if len(fused_boxes) > 0:
            fused_boxes = np.array(fused_boxes)
            fused_boxes[:, [0, 2]] *= w
            fused_boxes[:, [1, 3]] *= h

        order = np.argsort(-np.array(fused_scores)) if len(fused_scores) > 0 else []
        fused_preds = [(fused_labels[i], fused_boxes[i], fused_scores[i]) for i in order]

        matched_gt = set()
        for cls, box, score in fused_preds:
            cls = int(cls)
            best_iou, best_gt_idx = 0, -1
            for idx, gt in enumerate(gt_boxes):
                gt_key = (img_base, idx)
                if gt_key in matched_gt or int(gt[0]) != cls:
                    continue
                iou = calculate_iou(box, gt[1:])
                if iou > best_iou:
                    best_iou, best_gt_idx = iou, idx
            is_tp = best_iou >= EVAL_IOU
            if is_tp:
                matched_gt.add((img_base, best_gt_idx))
            class_detections[cls].append((score, is_tp))

    aps = []
    for cls_id in range(NUM_CLASSES):
        dets = sorted(class_detections[cls_id], key=lambda x: x[0], reverse=True)
        n_gt = class_gt_counts[cls_id]
        if n_gt == 0 or len(dets) == 0:
            aps.append(0.0)
            continue
        tps = np.array([1 if d[1] else 0 for d in dets])
        fps = np.array([0 if d[1] else 1 for d in dets])
        tp_cum, fp_cum = np.cumsum(tps), np.cumsum(fps)
        recalls = tp_cum / (n_gt + 1e-9)
        precisions = tp_cum / (tp_cum + fp_cum + 1e-9)
        aps.append(compute_ap(recalls, precisions))

    return float(np.mean(aps))


def score_single_model_from_cache(model_name, cache, image_bases, labels_dir):
    """Standalone AP50 for one model, straight from its cached predictions.
    Diagnostic only -- not used to pick anything."""
    class_detections = {c: [] for c in range(NUM_CLASSES)}
    class_gt_counts  = {c: 0 for c in range(NUM_CLASSES)}
    for img_base in image_bases:
        entry = cache[model_name][img_base]
        w, h = entry['w'], entry['h']
        label_path = os.path.join(labels_dir, f'{img_base}.txt')
        gt_boxes = load_yolo_labels(label_path, w, h)
        for gt in gt_boxes:
            class_gt_counts[int(gt[0])] += 1

        boxes = np.array(entry['boxes'])
        if len(boxes) > 0:
            boxes = boxes.copy()
            boxes[:, [0, 2]] *= w
            boxes[:, [1, 3]] *= h
        scores = entry['scores']
        labels = entry['labels']
        order = np.argsort(-np.array(scores)) if len(scores) > 0 else []

        matched_gt = set()
        for i in order:
            cls = int(labels[i])
            box = boxes[i]
            score = scores[i]
            best_iou, best_gt_idx = 0, -1
            for idx, gt in enumerate(gt_boxes):
                gt_key = (img_base, idx)
                if gt_key in matched_gt or int(gt[0]) != cls:
                    continue
                iou = calculate_iou(box, gt[1:])
                if iou > best_iou:
                    best_iou, best_gt_idx = iou, idx
            is_tp = best_iou >= EVAL_IOU
            if is_tp:
                matched_gt.add((img_base, best_gt_idx))
            class_detections[cls].append((score, is_tp))

    aps = []
    for cls_id in range(NUM_CLASSES):
        dets = sorted(class_detections[cls_id], key=lambda x: x[0], reverse=True)
        n_gt = class_gt_counts[cls_id]
        if n_gt == 0 or len(dets) == 0:
            aps.append(0.0)
            continue
        tps = np.array([1 if d[1] else 0 for d in dets])
        fps = np.array([0 if d[1] else 1 for d in dets])
        tp_cum, fp_cum = np.cumsum(tps), np.cumsum(fps)
        recalls = tp_cum / (n_gt + 1e-9)
        precisions = tp_cum / (tp_cum + fp_cum + 1e-9)
        aps.append(compute_ap(recalls, precisions))
    return float(np.mean(aps))


# ─────────────────────────────────────────────────────────────────────────────
# STEP 1 — STANDALONE VAL mAP50 PER MODEL (diagnostic only, computed fresh)
# ─────────────────────────────────────────────────────────────────────────────
print(f"\n{'='*70}\nSTEP 1 — Building VAL prediction cache + standalone VAL mAP50 per model\n{'='*70}")

val_cache, val_image_bases = build_prediction_cache(MODEL_NAMES, VAL_IMAGES_DIR, cache_tag='val')

solo_val_map50 = {}
for m_name in MODEL_NAMES:
    solo_val_map50[m_name] = score_single_model_from_cache(m_name, val_cache, val_image_bases, VAL_LABELS_DIR)
    print(f"  {m_name:<12s} standalone VAL mAP50 = {solo_val_map50[m_name]:.4f}")

# ─────────────────────────────────────────────────────────────────────────────
# STEP 2 — COMBINATION SEARCH ON VALIDATION (using cached predictions)
# ─────────────────────────────────────────────────────────────────────────────
print(f"\n{'='*70}\nSTEP 2 — Searching model SUBSETS on VALIDATION (equal weights, fixed IoU={WBF_IOU_FIXED})\n{'='*70}")

combo_results = []
for size in range(MIN_COMBO_SIZE, MAX_COMBO_SIZE + 1):
    for combo in itertools.combinations(MODEL_NAMES, size):
        weights = [1.0] * len(combo)
        val_map50 = score_combo_from_cache(list(combo), weights, WBF_IOU_FIXED, val_cache, val_image_bases, VAL_LABELS_DIR)
        combo_results.append({'models': list(combo), 'val_map50': val_map50})

combo_results.sort(key=lambda x: x['val_map50'], reverse=True)
print(f"\nTop 10 combinations on VAL:")
for r in combo_results[:10]:
    print(f"  VAL mAP50={r['val_map50']:.4f}  {r['models']}")

winning_models = combo_results[0]['models']
print(f"\n>> Winning combination (chosen on VAL): {winning_models} "
      f"(VAL mAP50={combo_results[0]['val_map50']:.4f})")

# ─────────────────────────────────────────────────────────────────────────────
# STEP 3 — HYPERPARAMETER TUNING FOR THE WINNING COMBO, ON VALIDATION ONLY
# ─────────────────────────────────────────────────────────────────────────────
print(f"\n{'='*70}\nSTEP 3 — Tuning WBF iou_thr / weights on VALIDATION data\n{'='*70}")

N = len(winning_models)
solo_scores = np.array([solo_val_map50[m] for m in winning_models])
weight_strategies = {
    'equal': [1.0] * N,
    'solo_map50_proportional': (solo_scores / solo_scores.max() * 1.5 + 0.5).round(3).tolist(),
}

best_val_mAP = -1.0
best_hyperparams = {}
for current_iou in IOU_SEARCH_SPACE:
    for strat_name, current_weights in weight_strategies.items():
        val_mAP = score_combo_from_cache(winning_models, current_weights, current_iou, val_cache, val_image_bases, VAL_LABELS_DIR)
        print(f"  IoU={current_iou:.2f} | weights[{strat_name}]={current_weights} -> VAL mAP50={val_mAP:.4f}")
        if val_mAP > best_val_mAP:
            best_val_mAP = val_mAP
            best_hyperparams = {'iou_thr': current_iou, 'weights': current_weights, 'weight_strategy': strat_name}

print(f"\n>> Best hyperparameters (chosen on VAL): {best_hyperparams} "
      f"(VAL mAP50={best_val_mAP:.4f})")

# ─────────────────────────────────────────────────────────────────────────────
# STEP 4 — SINGLE, FINAL EVALUATION ON TEST (touched exactly once)
# ─────────────────────────────────────────────────────────────────────────────
print(f"\n{'='*70}\nSTEP 4 — Final one-time evaluation on TEST data\n{'='*70}")

test_cache, test_image_bases = build_prediction_cache(winning_models, TEST_IMAGES_DIR, cache_tag='test')

final_test_mAP50 = score_combo_from_cache(
    winning_models, best_hyperparams['weights'], best_hyperparams['iou_thr'],
    test_cache, test_image_bases, TEST_LABELS_DIR
)

print(f"\n⭐ FINAL REPORTED RESULT ⭐")
print(f"  Combination   : {winning_models}")
print(f"  iou_thr       : {best_hyperparams['iou_thr']}")
print(f"  weights       : {best_hyperparams['weights']}  ({best_hyperparams['weight_strategy']})")
print(f"  TEST mAP50    : {final_test_mAP50:.4f}")
print("\n(This is the only number computed on the test set. The combination")
print(" and hyperparameters were both selected using VAL only, from cached")
print(" predictions, and no solo mAP50 from a prior run was used to decide")
print(" anything -- Step 1's solo scores were computed fresh and only feed")
print(" into the 'solo_map50_proportional' weight strategy as one option")
print(" among several tried in Step 3.)")

# ─────────────────────────────────────────────────────────────────────────────
# STEP 4b — ENSEMBLE-SIZE ABLATION (supplementary, NOT the headline result)
# ─────────────────────────────────────────────────────────────────────────────
print(f"\n{'='*70}\nSTEP 4b — Ensemble-size ablation (VAL-selected combo per size, TEST scored once per size)\n{'='*70}")

SIZES_TO_REPORT = sorted(set(len(r['models']) for r in combo_results))

best_combo_per_size = {}
for size in SIZES_TO_REPORT:
    sized = [r for r in combo_results if len(r['models']) == size]
    best_combo_per_size[size] = max(sized, key=lambda r: r['val_map50'])

models_needed_for_ablation = sorted(set(
    m for combo in best_combo_per_size.values() for m in combo['models']
))
ablation_test_cache, ablation_test_bases = build_prediction_cache(
    models_needed_for_ablation, TEST_IMAGES_DIR, cache_tag='test'
)

print(f"\n{'Size':<6}{'VAL mAP50':<12}{'TEST mAP50':<12}Combination")
ablation_rows = []
for size in SIZES_TO_REPORT:
    combo = best_combo_per_size[size]
    weights = [1.0] * size
    test_map50 = score_combo_from_cache(
        combo['models'], weights, WBF_IOU_FIXED,
        ablation_test_cache, ablation_test_bases, TEST_LABELS_DIR
    )
    ablation_rows.append({
        'size': size, 'models': combo['models'],
        'val_map50': combo['val_map50'], 'test_map50': test_map50,
    })
    print(f"{size:<6}{combo['val_map50']:<12.4f}{test_map50:<12.4f}{combo['models']}")

print("\nNOTE: this table is descriptive/supplementary. The Step 4 result above")
print("(combination+hyperparameters both chosen on VAL) remains the one number")
print("to report as THE result. Do not replace it with whichever row here has")
print("the highest TEST mAP50 -- that would reintroduce test-set leakage.")

# ─────────────────────────────────────────────────────────────────────────────
# STEP 5 — EXPORT FUSED LABELS + VISUALIZATIONS FOR THE TEST SET
# ─────────────────────────────────────────────────────────────────────────────
print("\nExporting fused labels and visualizations for the test set...")

test_image_paths = sorted(
    glob.glob(os.path.join(TEST_IMAGES_DIR, '*.jpg')) +
    glob.glob(os.path.join(TEST_IMAGES_DIR, '*.png'))
)

for img_path in test_image_paths:
    img = cv2.imread(img_path)
    vis_img = img.copy()
    h, w = img.shape[:2]
    img_base = os.path.splitext(os.path.basename(img_path))[0]

    boxes_list, scores_list, labels_list = [], [], []
    for m_name in winning_models:
        entry = test_cache[m_name][img_base]
        boxes_list.append(entry['boxes'])
        scores_list.append(entry['scores'])
        labels_list.append(entry['labels'])

    fused_boxes, fused_scores, fused_labels = weighted_boxes_fusion(
        boxes_list, scores_list, labels_list,
        weights=best_hyperparams['weights'],
        iou_thr=best_hyperparams['iou_thr'],
        skip_box_thr=0.0001,
    )

    txt_out_path = os.path.join(OUTPUT_LABELS_DIR, f"{img_base}.txt")
    with open(txt_out_path, 'w') as f:
        for box, label, score in zip(fused_boxes, fused_labels, fused_scores):
            if score < 0.25:
                continue
            x1, y1, x2, y2 = box
            box_w, box_h = x2 - x1, y2 - y1
            xc, yc = x1 + box_w / 2, y1 + box_h / 2
            f.write(f"{int(label)} {xc:.6f} {yc:.6f} {box_w:.6f} {box_h:.6f}\n")

    if len(fused_boxes) > 0:
        fb = np.array(fused_boxes)
        fb[:, [0, 2]] *= w
        fb[:, [1, 3]] *= h
        for box, label, score in zip(fb, fused_labels, fused_scores):
            if score < 0.25:
                continue
            x1, y1, x2, y2 = map(int, box)
            cv2.rectangle(vis_img, (x1, y1), (x2, y2), (0, 0, 255), 3)
            caption = f"{CLASS_NAMES[int(label)]}: {score:.2f}"
            cv2.putText(vis_img, caption, (x1, max(y1 - 10, 15)),
                        cv2.FONT_HERSHEY_SIMPLEX, 0.5, (0, 0, 255), 2)

    cv2.imwrite(os.path.join(OUTPUT_VIS_DIR, f"{img_base}_fused.png"), vis_img)

print(f"\nDone. Outputs saved to:")
print(f"   --> Labels        : {OUTPUT_LABELS_DIR}")
print(f"   --> Visualizations: {OUTPUT_VIS_DIR}")
print(f"   --> Prediction cache (reusable across runs): {CACHE_DIR}")

import os, pickle
import numpy as np

from google.colab import drive
drive.mount('/content/drive')

# ── Config (same as main script) ────────────────────────────────────────────
BASE_DIR       = '/content/drive/MyDrive/CR1'
VAL_LABELS_DIR = f'{BASE_DIR}/valid/labels'
CACHE_DIR      = f'{BASE_DIR}/CariesDet_Scaling/_wbf_pred_cache'
CLASS_NAMES    = ['dentin-caries', 'enamel-caries']
NUM_CLASSES    = len(CLASS_NAMES)
EVAL_IOU       = 0.50
WBF_IOU_FIXED  = 0.55   # matches the fixed IoU used throughout the ablation table

try:
    from ensemble_boxes import weighted_boxes_fusion
except ImportError:
    os.system('pip install ensemble-boxes -q')
    from ensemble_boxes import weighted_boxes_fusion

# ── Combinations to score (edit this list freely) ───────────────────────────
COMBINATIONS_TO_RUN = [
    ('2-model (VAL-selected)',      ['YOLOv8s', 'RTDETR-L']),
    ('2-model (comparison)',        ['YOLO11s', 'YOLOv8s']),
    ('3-model',                     ['YOLOv8s', 'YOLOv9s', 'RTDETR-L']),
    ('4-model',                     ['YOLOv8s', 'YOLOv8m', 'YOLOv9s', 'RTDETR-L']),
    ('5-model',                     ['YOLOv8s', 'YOLOv8m', 'YOLOv9s', 'YOLOv10s', 'RTDETR-L']),
    ('6-model (reported ensemble)', ['YOLO11s', 'YOLOv8s', 'YOLOv8m', 'YOLOv9s', 'YOLOv10s', 'RTDETR-L']),
    ('7-model',                     ['YOLO11s', 'YOLO11m', 'YOLOv8s', 'YOLOv8m', 'YOLOv9s', 'YOLOv10s', 'RTDETR-L']),
    ('8-model (all)',               ['YOLO11n', 'YOLO11s', 'YOLO11m', 'YOLOv8s', 'YOLOv8m', 'YOLOv9s', 'YOLOv10s', 'RTDETR-L']),
]

# ── Helpers ───────────────────────────────────────────────────────────────
def load_yolo_labels(label_path, img_w, img_h):
    if not os.path.exists(label_path):
        return np.zeros((0, 5))
    boxes = []
    with open(label_path) as f:
        for line in f:
            parts = line.strip().split()
            if len(parts) < 5:
                continue
            cls, x_c, y_c, w, h = map(float, parts[:5])
            x1 = (x_c - w / 2) * img_w
            y1 = (y_c - h / 2) * img_h
            x2 = (x_c + w / 2) * img_w
            y2 = (y_c + h / 2) * img_h
            boxes.append([cls, x1, y1, x2, y2])
    return np.array(boxes) if boxes else np.zeros((0, 5))


def calculate_iou(boxA, boxB):
    xA, yA = max(boxA[0], boxB[0]), max(boxA[1], boxB[1])
    xB, yB = min(boxA[2], boxB[2]), min(boxA[3], boxB[3])
    interArea = max(0, xB - xA) * max(0, yB - yA)
    boxAArea = (boxA[2] - boxA[0]) * (boxA[3] - boxA[1])
    boxBArea = (boxB[2] - boxB[0]) * (boxB[3] - boxB[1])
    return interArea / float(boxAArea + boxBArea - interArea + 1e-6)


def compute_ap(recalls, precisions):
    recalls = np.concatenate(([0.0], recalls, [1.0]))
    precisions = np.concatenate(([0.0], precisions, [0.0]))
    for i in range(len(precisions) - 2, -1, -1):
        precisions[i] = max(precisions[i], precisions[i + 1])
    idx = np.where(recalls[1:] != recalls[:-1])[0]
    return np.sum((recalls[idx + 1] - recalls[idx]) * precisions[idx + 1])


def load_cache(model_name, cache_tag='val'):
    cache_path = os.path.join(CACHE_DIR, f'{cache_tag}__{model_name}.pkl')
    if not os.path.exists(cache_path):
        raise FileNotFoundError(
            f"No cached VAL predictions for {model_name} at {cache_path}. "
            f"This model wasn't cached in earlier runs -- reload its .pt weights "
            f"and run inference once over {VAL_LABELS_DIR.replace('labels','images')} "
            f"before scoring combinations that include it."
        )
    with open(cache_path, 'rb') as f:
        return pickle.load(f)


def score_combo_from_cache(model_list, weights, iou_thr, cache, image_bases, labels_dir):
    class_detections = {c: [] for c in range(NUM_CLASSES)}
    class_gt_counts  = {c: 0 for c in range(NUM_CLASSES)}

    for img_base in image_bases:
        w = cache[model_list[0]][img_base]['w']
        h = cache[model_list[0]][img_base]['h']
        label_path = os.path.join(labels_dir, f'{img_base}.txt')
        gt_boxes = load_yolo_labels(label_path, w, h)
        for gt in gt_boxes:
            class_gt_counts[int(gt[0])] += 1

        boxes_list, scores_list, labels_list = [], [], []
        for m_name in model_list:
            entry = cache[m_name][img_base]
            boxes_list.append(entry['boxes'])
            scores_list.append(entry['scores'])
            labels_list.append(entry['labels'])

        fused_boxes, fused_scores, fused_labels = weighted_boxes_fusion(
            boxes_list, scores_list, labels_list,
            weights=weights, iou_thr=iou_thr, skip_box_thr=0.0001
        )

        if len(fused_boxes) > 0:
            fused_boxes = np.array(fused_boxes)
            fused_boxes[:, [0, 2]] *= w
            fused_boxes[:, [1, 3]] *= h

        order = np.argsort(-np.array(fused_scores)) if len(fused_scores) > 0 else []
        fused_preds = [(fused_labels[i], fused_boxes[i], fused_scores[i]) for i in order]

        matched_gt = set()
        for cls, box, score in fused_preds:
            cls = int(cls)
            best_iou, best_gt_idx = 0, -1
            for idx, gt in enumerate(gt_boxes):
                gt_key = (img_base, idx)
                if gt_key in matched_gt or int(gt[0]) != cls:
                    continue
                iou = calculate_iou(box, gt[1:])
                if iou > best_iou:
                    best_iou, best_gt_idx = iou, idx
            is_tp = best_iou >= EVAL_IOU
            if is_tp:
                matched_gt.add((img_base, best_gt_idx))
            class_detections[cls].append((score, is_tp))

    aps = []
    for cls_id in range(NUM_CLASSES):
        dets = sorted(class_detections[cls_id], key=lambda x: x[0], reverse=True)
        n_gt = class_gt_counts[cls_id]
        if n_gt == 0 or len(dets) == 0:
            aps.append(0.0)
            continue
        tps = np.array([1 if d[1] else 0 for d in dets])
        fps = np.array([0 if d[1] else 1 for d in dets])
        tp_cum, fp_cum = np.cumsum(tps), np.cumsum(fps)
        recalls = tp_cum / (n_gt + 1e-9)
        precisions = tp_cum / (tp_cum + fp_cum + 1e-9)
        aps.append(compute_ap(recalls, precisions))
    return float(np.mean(aps))


# ── Load VAL cache for every model referenced across all combinations ──────
all_models_needed = sorted(set(m for _, models in COMBINATIONS_TO_RUN for m in models))
print(f"Loading VAL prediction caches for: {all_models_needed}\n")
val_cache = {m: load_cache(m, 'val') for m in all_models_needed}
val_bases = sorted(val_cache[all_models_needed[0]].keys())

# ── Score every combination, equal weights, fixed IoU (matches the table) ──
print(f"{'Combination':<32}{'VAL mAP50':<12}Models")
results = []
for label, models in COMBINATIONS_TO_RUN:
    weights = [1.0] * len(models)
    score = score_combo_from_cache(models, weights, WBF_IOU_FIXED, val_cache, val_bases, VAL_LABELS_DIR)
    results.append((label, score, models))
    print(f"{label:<32}{score:<12.4f}{models}")

print("\nDone. All numbers computed on VALIDATION only -- test set was not touched.")

