import os, pickle
import numpy as np

from google.colab import drive
drive.mount('/content/drive')

BASE_DIR        = '/content/drive/MyDrive/CR1'
TEST_LABELS_DIR = f'{BASE_DIR}/test/labels'
CACHE_DIR       = f'{BASE_DIR}/CariesDet_Scaling/_wbf_pred_cache'
CLASS_NAMES     = ['dentin-caries', 'enamel-caries']
NUM_CLASSES     = len(CLASS_NAMES)
EVAL_IOU        = 0.50

MODELS_TO_SCORE = ['YOLO11n', 'YOLO11s', 'YOLO11m', 'YOLOv8s', 'YOLOv8m', 'YOLOv9s', 'YOLOv10s', 'RTDETR-L']

REPORTED_ENSEMBLE_TEST_MAP50 = 0.8319  # from Step 4, for direct comparison


def load_yolo_labels(label_path, img_w, img_h):
    if not os.path.exists(label_path):
        return np.zeros((0, 5))
    boxes = []
    with open(label_path) as f:
        for line in f:
            parts = line.strip().split()
            if len(parts) < 5:
                continue
            cls, x_c, y_c, w, h = map(float, parts[:5])
            x1 = (x_c - w / 2) * img_w
            y1 = (y_c - h / 2) * img_h
            x2 = (x_c + w / 2) * img_w
            y2 = (y_c + h / 2) * img_h
            boxes.append([cls, x1, y1, x2, y2])
    return np.array(boxes) if boxes else np.zeros((0, 5))


def calculate_iou(boxA, boxB):
    xA, yA = max(boxA[0], boxB[0]), max(boxA[1], boxB[1])
    xB, yB = min(boxA[2], boxB[2]), min(boxA[3], boxB[3])
    interArea = max(0, xB - xA) * max(0, yB - yA)
    boxAArea = (boxA[2] - boxA[0]) * (boxA[3] - boxA[1])
    boxBArea = (boxB[2] - boxB[0]) * (boxB[3] - boxB[1])
    return interArea / float(boxAArea + boxBArea - interArea + 1e-6)


def compute_ap(recalls, precisions):
    recalls = np.concatenate(([0.0], recalls, [1.0]))
    precisions = np.concatenate(([0.0], precisions, [0.0]))
    for i in range(len(precisions) - 2, -1, -1):
        precisions[i] = max(precisions[i], precisions[i + 1])
    idx = np.where(recalls[1:] != recalls[:-1])[0]
    return np.sum((recalls[idx + 1] - recalls[idx]) * precisions[idx + 1])


def load_cache(model_name, cache_tag):
    cache_path = os.path.join(CACHE_DIR, f'{cache_tag}__{model_name}.pkl')
    if not os.path.exists(cache_path):
        raise FileNotFoundError(f"No cached {cache_tag} predictions for {model_name} at {cache_path}.")
    with open(cache_path, 'rb') as f:
        return pickle.load(f)


def score_single_model_from_cache(model_name, cache, image_bases, labels_dir):
    """Standalone mAP50 for one model, straight from its cached predictions
    (uses ALL predictions ranked by score, not a fixed conf threshold --
    this matches how mAP is normally computed, unlike the fixed-threshold
    F1 used in table6)."""
    class_detections = {c: [] for c in range(NUM_CLASSES)}
    class_gt_counts  = {c: 0 for c in range(NUM_CLASSES)}
    for img_base in image_bases:
        entry = cache[model_name][img_base]
        w, h = entry['w'], entry['h']
        label_path = os.path.join(labels_dir, f'{img_base}.txt')
        gt_boxes = load_yolo_labels(label_path, w, h)
        for gt in gt_boxes:
            class_gt_counts[int(gt[0])] += 1

        boxes = np.array(entry['boxes'])
        if len(boxes) > 0:
            boxes = boxes.copy()
            boxes[:, [0, 2]] *= w
            boxes[:, [1, 3]] *= h
        scores = entry['scores']
        labels = entry['labels']
        order = np.argsort(-np.array(scores)) if len(scores) > 0 else []

        matched_gt = set()
        for i in order:
            cls = int(labels[i])
            box = boxes[i]
            score = scores[i]
            best_iou, best_gt_idx = 0, -1
            for idx, gt in enumerate(gt_boxes):
                gt_key = (img_base, idx)
                if gt_key in matched_gt or int(gt[0]) != cls:
                    continue
                iou = calculate_iou(box, gt[1:])
                if iou > best_iou:
                    best_iou, best_gt_idx = iou, idx
            is_tp = best_iou >= EVAL_IOU
            if is_tp:
                matched_gt.add((img_base, best_gt_idx))
            class_detections[cls].append((score, is_tp))

    aps = []
    for cls_id in range(NUM_CLASSES):
        dets = sorted(class_detections[cls_id], key=lambda x: x[0], reverse=True)
        n_gt = class_gt_counts[cls_id]
        if n_gt == 0 or len(dets) == 0:
            aps.append(0.0)
            continue
        tps = np.array([1 if d[1] else 0 for d in dets])
        fps = np.array([0 if d[1] else 1 for d in dets])
        tp_cum, fp_cum = np.cumsum(tps), np.cumsum(fps)
        recalls = tp_cum / (n_gt + 1e-9)
        precisions = tp_cum / (tp_cum + fp_cum + 1e-9)
        aps.append(compute_ap(recalls, precisions))
    return float(np.mean(aps))


print(f"Loading TEST caches for: {MODELS_TO_SCORE}\n")
test_cache = {}
for m in MODELS_TO_SCORE:
    try:
        test_cache[m] = load_cache(m, 'test')
    except FileNotFoundError as e:
        print(f"  SKIP {m}: {e}")

test_bases = sorted(next(iter(test_cache.values())).keys())
print(f"{len(test_bases)} test images.\n")

print(f"{'='*70}\nSolo TEST mAP50 per model\n{'='*70}")
solo_test_map50 = {}
for m in test_cache:
    score = score_single_model_from_cache(m, test_cache, test_bases, TEST_LABELS_DIR)
    solo_test_map50[m] = score
    print(f"  {m:<12s} TEST mAP50 = {score:.4f}")

