print(f">> Gap (ensemble - leading single model): +{gap:.4f}")



import os, sys, glob, json, argparse
import numpy as np
import pandas as pd

# ─────────────────────────── CONFIG (edit only here) ────────────────────────
BASE_DIR   = os.environ.get('CARIES_BASE', '/content/drive/MyDrive/CR1')
TEST_IMG   = f'{BASE_DIR}/test/images'
TEST_LBL   = f'{BASE_DIR}/test/labels'
RUNS       = f'{BASE_DIR}/CariesDet_Scaling'
OUT_DIR    = f'{RUNS}/Reconciled'

CLASS_NAMES = ['dentin-caries', 'enamel-caries']          # YOLO class ids 0, 1
NC = len(CLASS_NAMES)

# name -> (kind, checkpoint).  kind: 'yolo' | 'rtdetr' | 'frcnn'
MODELS = {
    'YOLOv11n':     ('yolo',   f'{RUNS}/CariesDet_yolo11n/weights/best.pt'),
    'YOLOv11s':     ('yolo',   f'{RUNS}/CariesDet_yolo11s/weights/best.pt'),
    'YOLOv11m':     ('yolo',   f'{RUNS}/CariesDet_yolo11m/weights/best.pt'),
    'YOLOv8s':      ('yolo',   f'{RUNS}/CariesDet_YOLOv8s/weights/best.pt'),
    'YOLOv8m':      ('yolo',   f'{RUNS}/CariesDet_YOLOv8m/weights/best.pt'),
    'YOLOv9s':      ('yolo',   f'{RUNS}/CariesDet_YOLOv9s/weights/best.pt'),
    'YOLOv10s':     ('yolo',   f'{RUNS}/CariesDet_YOLOv10s/weights/best.pt'),
    'RT-DETR-L':    ('rtdetr', f'{RUNS}/CariesDet_RT-DETR-L/weights/best.pt'),
    'Faster R-CNN': ('frcnn',  f'{RUNS}/FasterRCNN/best.pth'),
}

# The ensemble you REPORT in the paper. Weights must be the exact frozen validation-derived
# values (manuscript says ~0.51 / ~0.49) - replace with the unrounded numbers.
ENSEMBLE = dict(name='YOLOv8s + YOLOv11s', members=['YOLOv8s', 'YOLOv11s'],
                weights=[0.51, 0.49], iou_thr=0.50, skip_box_thr=0.001)
BASELINE = 'YOLOv8s'                 # single model the ensemble is compared against

CONF_OP      = 0.25    # fixed operating point. State in Methods HOW it was chosen
                       # (a-priori default? chosen on validation?) - never on test.
IOU_MATCH    = 0.50
PRED_CONF    = 0.001   # keep everything so mAP uses the full PR curve
PRED_NMS_IOU = 0.70    # Ultralytics val default
IMGSZ        = 640
N_BOOT       = 1000
SEED         = 42
FPI_GRID     = [0.25, 0.5, 1.0, 2.0]
IOUS         = np.round(np.arange(0.5, 0.96, 0.05), 2)   # 0.50 ... 0.95

# ─────────────────────────────── DATA / INFERENCE ───────────────────────────
def list_images(d):
    ps = []
    for e in ('*.jpg', '*.jpeg', '*.png', '*.bmp'):
        ps += glob.glob(os.path.join(d, e))
    return sorted(ps)


def load_gts(img_paths, lbl_dir):
    from PIL import Image
    gts = {}
    for p in img_paths:
        stem = os.path.splitext(os.path.basename(p))[0]
        W, H = Image.open(p).size
        b, c = [], []
        lp = os.path.join(lbl_dir, stem + '.txt')
        if os.path.exists(lp):
            for line in open(lp):
                t = line.split()
                if len(t) < 5:
                    continue
                k, cx, cy, bw, bh = int(float(t[0])), *map(float, t[1:5])
                b.append([(cx - bw / 2) * W, (cy - bh / 2) * H, (cx + bw / 2) * W, (cy + bh / 2) * H])
                c.append(k)
        gts[stem] = dict(boxes=np.array(b, float).reshape(-1, 4), cls=np.array(c, int), w=W, h=H)
    return gts


def predict_model(kind, ckpt, img_paths):
    """Returns {stem: (boxes_xyxy_px, scores, classes0)} at conf>=PRED_CONF."""
    out = {}
    if kind in ('yolo', 'rtdetr'):
        from ultralytics import YOLO, RTDETR
        model = (RTDETR if kind == 'rtdetr' else YOLO)(ckpt)
        for p in img_paths:
            r = model.predict(p, conf=PRED_CONF, iou=PRED_NMS_IOU, imgsz=IMGSZ,
                              max_det=300, verbose=False)[0]
            stem = os.path.splitext(os.path.basename(p))[0]
            if r.boxes is None or len(r.boxes) == 0:
                out[stem] = (np.zeros((0, 4)), np.zeros(0), np.zeros(0, int))
            else:
                out[stem] = (r.boxes.xyxy.cpu().numpy().astype(float),
                             r.boxes.conf.cpu().numpy().astype(float),
                             r.boxes.cls.cpu().numpy().astype(int))
        return out
    import torch
    from PIL import Image
    from torchvision.transforms import functional as TF
    from torchvision.models.detection import fasterrcnn_resnet50_fpn_v2
    dev = torch.device('cuda' if torch.cuda.is_available() else 'cpu')
    model = fasterrcnn_resnet50_fpn_v2(weights=None, weights_backbone=None, num_classes=NC + 1)
    st = torch.load(ckpt, map_location='cpu')
    if isinstance(st, dict) and not any(k.startswith(('backbone', 'rpn', 'roi_heads')) for k in st):
        st = st.get('model', st.get('state_dict', st))
    model.load_state_dict(st)
    model.roi_heads.score_thresh = PRED_CONF
    model.roi_heads.detections_per_img = 300
    model.eval().to(dev)
    for p in img_paths:
        stem = os.path.splitext(os.path.basename(p))[0]
        with torch.no_grad():
            o = model([TF.to_tensor(Image.open(p).convert('RGB')).to(dev)])[0]
        out[stem] = (o['boxes'].cpu().numpy().astype(float), o['scores'].cpu().numpy().astype(float),
                     o['labels'].cpu().numpy().astype(int) - 1)       # torchvision is 1-indexed
    return out


def wbf_fuse(preds, gts, members, weights, iou_thr, skip_thr):
    from ensemble_boxes import weighted_boxes_fusion
    out = {}
    for stem, g in gts.items():
        sc = np.array([g['w'], g['h'], g['w'], g['h']], float)
        bl, sl, ll = [], [], []
        for m in members:
            b, s, c = preds[m][stem]
            bl.append(np.clip(b / sc, 0, 1).tolist() if len(s) else [])
            sl.append(s.tolist()); ll.append(c.tolist())
        if all(len(s) == 0 for s in sl):
            out[stem] = (np.zeros((0, 4)), np.zeros(0), np.zeros(0, int)); continue
        fb, fs, fl = weighted_boxes_fusion(bl, sl, ll, weights=weights,
                                           iou_thr=iou_thr, skip_box_thr=skip_thr)
        out[stem] = (np.asarray(fb).reshape(-1, 4) * sc, np.asarray(fs), np.asarray(fl).astype(int))
    return out

# ─────────────────────────────── MATCHING / METRICS ─────────────────────────
def iou_matrix(a, b):
    a = np.asarray(a, float).reshape(-1, 4); b = np.asarray(b, float).reshape(-1, 4)
    ix1 = np.maximum(a[:, None, 0], b[None, :, 0]); iy1 = np.maximum(a[:, None, 1], b[None, :, 1])
    ix2 = np.minimum(a[:, None, 2], b[None, :, 2]); iy2 = np.minimum(a[:, None, 3], b[None, :, 3])
    inter = np.clip(ix2 - ix1, 0, None) * np.clip(iy2 - iy1, 0, None)
    aa = (a[:, 2] - a[:, 0]) * (a[:, 3] - a[:, 1]); ab = (b[:, 2] - b[:, 0]) * (b[:, 3] - b[:, 1])
    return inter / (aa[:, None] + ab[None, :] - inter + 1e-9)


def match_image(pb, ps, pc, gb, gc, thr):
    """Greedy one-to-one, descending score, class-aware. Returns TP flag per prediction.
    A detection's flag depends only on higher-scored detections, so thresholding the
    list at any confidence leaves the flags of the surviving detections unchanged."""
    tp = np.zeros(len(ps), bool)
    if len(ps) == 0 or len(gb) == 0:
        return tp
    ious = iou_matrix(pb, gb); used = np.zeros(len(gb), bool)
    for i in np.argsort(-ps, kind='stable'):
        cand = np.where((gc == pc[i]) & ~used)[0]
        if len(cand) == 0:
            continue
        j = cand[np.argmax(ious[i, cand])]
        if ious[i, j] >= thr:
            tp[i] = True; used[j] = True
    return tp


_trapz = getattr(np, 'trapezoid', None) or np.trapz


def ap101(tp, wts, ngt):
    if ngt <= 0:
        return np.nan
    tpc = np.cumsum(wts * tp); fpc = np.cumsum(wts * (~tp))
    rec = tpc / ngt; prec = tpc / np.maximum(tpc + fpc, 1e-12)
    mrec = np.concatenate(([0.], rec, [1.])); mpre = np.concatenate(([1.], prec, [0.]))
    mpre = np.flip(np.maximum.accumulate(np.flip(mpre)))
    x = np.linspace(0, 1, 101)
    return float(_trapz(np.interp(x, mrec, mpre), x))


class Dets:
    """All detections of one model, matched once at every IoU in IOUS, sorted by score."""
    def __init__(self, pred, gts, stems):
        self.n_img = len(stems)
        self.n_gt = np.zeros((self.n_img, NC))
        per = {c: ([], [], []) for c in range(NC)}
        for k, stem in enumerate(stems):
            g = gts[stem]
            for c in range(NC):
                self.n_gt[k, c] = (g['cls'] == c).sum()
            b, s, c_ = pred[stem]
            if len(s) == 0:
                continue
            tp = np.stack([match_image(b, s, c_, g['boxes'], g['cls'], t) for t in IOUS], 1)
            for c in range(NC):
                m = c_ == c
                per[c][0].append(s[m]); per[c][1].append(np.full(m.sum(), k)); per[c][2].append(tp[m])
        self.cls_d = {}
        for c in range(NC):
            s = np.concatenate(per[c][0]) if per[c][0] else np.zeros(0)
            i = np.concatenate(per[c][1]) if per[c][1] else np.zeros(0, int)
            t = np.concatenate(per[c][2]) if per[c][2] else np.zeros((0, len(IOUS)), bool)
            o = np.argsort(-s, kind='stable')
            self.cls_d[c] = (s[o], i[o], t[o])


def metrics(d, w=None, full=False):
    """w = image weights (bootstrap multiplicities); None -> all ones."""
    w = np.ones(d.n_img) if w is None else w
    gtw = (w[:, None] * d.n_gt).sum(0)
    res = {'cls': {}}; TP = FP = FN = 0.0; ap50, ap_all = [], []
    for c in range(NC):
        s, i, t = d.cls_d[c]; dw = w[i]; k = s >= CONF_OP
        tp = float((dw[k] * t[k, 0]).sum()); fp = float((dw[k] * (~t[k, 0])).sum()); fn = float(gtw[c] - tp)
        TP += tp; FP += fp; FN += fn
        p = tp / (tp + fp) if tp + fp > 0 else 0.0; r = tp / (tp + fn) if tp + fn > 0 else 0.0
        res['cls'][c] = dict(TP=tp, FP=fp, FN=fn, P=p, R=r,
                             F1=2 * p * r / (p + r) if p + r > 0 else 0.0,
                             FPI=fp / w.sum(), AP50=ap101(t[:, 0], dw, gtw[c]))
        ap50.append(res['cls'][c]['AP50'])
        if full:
            ap_all.append([ap101(t[:, j], dw, gtw[c]) for j in range(len(IOUS))])
    P = TP / (TP + FP) if TP + FP > 0 else 0.0; R = TP / (TP + FN) if TP + FN > 0 else 0.0
    res.update(TP=TP, FP=FP, FN=FN, P=P, R=R, F1=2 * P * R / (P + R) if P + R > 0 else 0.0,
               FPI=FP / w.sum(), mAP50=float(np.nanmean(ap50)))
    if full:
        res['mAP50_95'] = float(np.nanmean(np.array(ap_all)))
    return res


def froc(d, cls=None):
    cs = list(range(NC)) if cls is None else [cls]
    s = np.concatenate([d.cls_d[c][0] for c in cs]); t = np.concatenate([d.cls_d[c][2][:, 0] for c in cs])
    o = np.argsort(-s, kind='stable'); t = t[o]
    ngt = d.n_gt[:, cs].sum()
    return np.cumsum(~t) / d.n_img, np.cumsum(t) / ngt


def sens_at(fpi, sens, x):
    m = fpi <= x
    return float(sens[m].max()) if m.any() else 0.0


def pct(a):
    return float(np.percentile(a, 2.5)), float(np.percentile(a, 97.5))

# ─────────────────────────────────── ANALYSIS ───────────────────────────────
def analyze(preds, gts, stems, out_dir, ens_name, base_name, n_boot=N_BOOT):
    os.makedirs(out_dir, exist_ok=True)
    names = list(preds.keys())
    D = {m: Dets(preds[m], gts, stems) for m in names}
    n = len(stems)
    rng = np.random.default_rng(SEED)                      # one shared resample set
    IDX = rng.integers(0, n, (n_boot, n))
    WB = np.stack([np.bincount(r, minlength=n) for r in IDX]).astype(float)

    pt, boot = {}, {}
    for m in names:
        pt[m] = metrics(D[m], full=True)
        rep = [metrics(D[m], WB[b]) for b in range(n_boot)]
        boot[m] = {k: np.array([r[k] for r in rep]) for k in ('P', 'R', 'F1', 'mAP50', 'FPI')}

    # ---- Table 2/3 unified (every number from one source) ----
    rows = []
    for m in names:
        r = pt[m]; row = {'Model': m}
        for lab, key in (('Precision', 'P'), ('Recall', 'R'), ('F1', 'F1'), ('mAP@0.50', 'mAP50')):
            lo, hi = pct(boot[m][key]); row[lab] = round(r[key], 4); row[lab + ' 95% CI'] = f'{lo:.4f}-{hi:.4f}'
        row['mAP@0.50:0.95'] = round(r['mAP50_95'], 4)
        row.update(TP=int(r['TP']), FP=int(r['FP']), FN=int(r['FN']), **{'FP/image': round(r['FPI'], 3)})
        rows.append(row)
    t23 = pd.DataFrame(rows); t23.to_csv(f'{out_dir}/table2_3_unified.csv', index=False)

    # ---- Table 6 class-wise (all models; use YOLOv8s + ensemble rows) ----
    rows = []
    for m in names:
        for c in range(NC):
            r = pt[m]['cls'][c]
            rows.append({'Model': m, 'Class': CLASS_NAMES[c], 'Precision': round(r['P'], 4),
                         'Recall': round(r['R'], 4), 'F1': round(r['F1'], 4), 'TP': int(r['TP']),
                         'FP': int(r['FP']), 'FN': int(r['FN']), 'FP/image': round(r['FPI'], 3),
                         'AP@0.50': round(r['AP50'], 4)})
    t6 = pd.DataFrame(rows); t6.to_csv(f'{out_dir}/table6_classwise.csv', index=False)

    # ---- Table 7 paired bootstrap: ensemble vs baseline ----
    rows = []
    for lab, key in (('mAP@0.50', 'mAP50'), ('Precision', 'P'), ('Recall', 'R'), ('F1', 'F1'),
                     ('FP/image', 'FPI')):
        diff = boot[ens_name][key] - boot[base_name][key]; lo, hi = pct(diff)
        rows.append({'Metric': lab, base_name: round(pt[base_name][key], 4),
                     ens_name: round(pt[ens_name][key], 4),
                     'Point difference': round(pt[ens_name][key] - pt[base_name][key], 4),
                     'Bootstrap mean difference': round(float(diff.mean()), 4),
                     '95% interval': f'{lo:+.4f} to {hi:+.4f}'})
    t7 = pd.DataFrame(rows); t7.to_csv(f'{out_dir}/table7_paired.csv', index=False)

    # ---- FROC / sensitivity at fixed FP per image ----
    import matplotlib; matplotlib.use('Agg'); import matplotlib.pyplot as plt
    fm = [base_name, ens_name]; rows = []
    fig, axs = plt.subplots(1, 3, figsize=(15, 4.2))
    for ax, (ttl, cls) in zip(axs, [('Overall', None), (CLASS_NAMES[0], 0), (CLASS_NAMES[1], 1)]):
        for m in fm:
            f, s = froc(D[m], cls); ax.step(f, s, where='post', label=m)
            rows.append({'Model': m, 'Class': ttl, **{f'Sens @ <= {x} FP/img': round(sens_at(f, s, x), 4)
                                                       for x in FPI_GRID}})
        ax.set_xlim(0, 3); ax.set_ylim(0, 1.02); ax.set_title(ttl); ax.set_xlabel('False positives per image')
        ax.set_ylabel('Sensitivity'); ax.grid(alpha=.3); ax.legend()
    fig.tight_layout(); fig.savefig(f'{out_dir}/froc.png', dpi=300); plt.close(fig)
    tf = pd.DataFrame(rows); tf.to_csv(f'{out_dir}/froc_sensitivity_at_fpi.csv', index=False)

    # ---- internal consistency checks ----
    for m in names:                                          # FROC cumulative == metrics() at CONF_OP
        f, s = froc(D[m]); k = (np.sort(np.concatenate([D[m].cls_d[c][0] for c in range(NC)]))[::-1] >= CONF_OP).sum()
        if k:
            assert abs(f[k - 1] * n - pt[m]['FP']) < 1e-6, f'{m}: FROC/metrics FP mismatch'
    print('consistency checks passed')

    cfg = dict(operating_point_conf=CONF_OP, iou_match=IOU_MATCH, pred_conf_floor=PRED_CONF,
               nms_iou=PRED_NMS_IOU, matching='greedy one-to-one, descending score, class-aware',
               prf1_averaging='micro (pooled over images and classes)',
               map='101-point interpolated AP, class-averaged, all predictions, IoU 0.50 / 0.50:0.95',
               bootstrap=f'{n_boot} image-level resamples, shared indices, seed {SEED}, percentile 95% interval',
               ensemble=ENSEMBLE, baseline=base_name, n_test_images=n)
    json.dump(cfg, open(f'{out_dir}/run_config.json', 'w'), indent=2)
    return t23, t6, t7, tf, cfg


def dump_predictions(preds, gts, stems, out_dir):
    rows = []
    for m, pr in preds.items():
        for stem in stems:
            b, s, c = pr[stem]; g = gts[stem]
            tp = match_image(b, s, c, g['boxes'], g['cls'], IOU_MATCH) if len(s) else np.zeros(0, bool)
            for j in range(len(s)):
                rows.append((m, stem, CLASS_NAMES[c[j]], float(s[j]), *map(float, b[j]), bool(tp[j])))
    pd.DataFrame(rows, columns=['model', 'image', 'class', 'score', 'x1', 'y1', 'x2', 'y2',
                                'matched_iou50']).to_csv(f'{out_dir}/predictions_test_all_models.csv.gz',
                                                         index=False, compression='gzip')
    gr = [(stem, CLASS_NAMES[k], *map(float, bx)) for stem in stems
          for bx, k in zip(gts[stem]['boxes'], gts[stem]['cls'])]
    pd.DataFrame(gr, columns=['image', 'class', 'x1', 'y1', 'x2', 'y2']).to_csv(
        f'{out_dir}/ground_truth_test.csv', index=False)


def methods_text(cfg):
    return (f"All detectors and the WBF ensemble were run once on the {cfg['n_test_images']} test images "
            f"(confidence floor {cfg['pred_conf_floor']}), and every reported test-set value was computed "
            f"from these saved predictions with a single script. Precision, recall, F1 and false positives "
            f"per image were computed at a fixed confidence threshold of {cfg['operating_point_conf']} "
            f"[STATE HOW/WHERE THIS THRESHOLD WAS CHOSEN] using {cfg['matching']} at IoU "
            f">= {cfg['iou_match']}, {cfg['prf1_averaging']}. mAP@0.50 and mAP@0.50:0.95 used "
            f"{cfg['map']}. Intervals are {cfg['bootstrap']}; paired differences use the same resamples.")

# ─────────────────────────────────── SELF-TEST ──────────────────────────────
def synthetic(n_img=24, seed=1):
    r = np.random.default_rng(seed); gts, stems = {}, []
    for k in range(n_img):
        stem = f'img{k:03d}'; stems.append(stem); n = r.integers(1, 4)
        xy = r.uniform(50, 450, (n, 2)); wh = r.uniform(30, 80, (n, 2))
        gts[stem] = dict(boxes=np.hstack([xy, xy + wh]), cls=r.integers(0, NC, n), w=640, h=640)
    def mk(skill, seed2):
        rr = np.random.default_rng(seed2); out = {}
        for stem in stems:
            g = gts[stem]; B, S, C = [], [], []
            for b, c in zip(g['boxes'], g['cls']):
                if rr.random() < skill:
                    B.append(b + rr.normal(0, 4, 4)); S.append(rr.uniform(0.3, 0.95)); C.append(c)
            for _ in range(rr.integers(0, 4)):
                xy = rr.uniform(0, 500, 2); B.append(np.r_[xy, xy + rr.uniform(30, 80, 2)])
                S.append(rr.uniform(0.001, 0.5)); C.append(rr.integers(0, NC))
            out[stem] = (np.array(B).reshape(-1, 4), np.array(S), np.array(C, int))
        return out
    return {'A': mk(0.8, 11), 'B': mk(0.7, 12), 'A + B': mk(0.85, 13)}, gts, stems


def selftest():
    import tempfile
    preds, gts, stems = synthetic(); out = tempfile.mkdtemp()
    t23, t6, t7, tf, cfg = analyze(preds, gts, stems, out, 'A + B', 'A', n_boot=200)
    dump_predictions(preds, gts, stems, out)
    pd.set_option('display.width', 250); pd.set_option('display.max_columns', 30)
    print(t23.to_string(index=False)); print(); print(t6.head(4).to_string(index=False))
    print(); print(t7.to_string(index=False)); print(); print(tf.to_string(index=False))
    # cross-check one number independently
    m = metrics(Dets(preds['A'], gts, stems)); tp = fp = fn = 0
    for stem in stems:
        b, s, c = preds['A'][stem]; k = s >= CONF_OP
        f = match_image(b[k], s[k], c[k], gts[stem]['boxes'], gts[stem]['cls'], 0.5)
        tp += f.sum(); fp += (~f).sum(); fn += len(gts[stem]['cls']) - f.sum()
    assert (m['TP'], m['FP'], m['FN']) == (tp, fp, fn), 'independent recount mismatch'
    print('\nselftest OK ->', out)

# ─────────────────────────────────────── MAIN ───────────────────────────────
def colab_setup():
    """Fresh-runtime setup: mount Drive, install deps, verify every path before any work."""
    try:
        from google.colab import drive
        if not os.path.isdir('/content/drive/MyDrive'):
            drive.mount('/content/drive')
    except ImportError:
        pass
    import importlib, subprocess
    for mod, pipname in (('ultralytics', 'ultralytics'), ('ensemble_boxes', 'ensemble-boxes')):
        try:
            importlib.import_module(mod)
        except ImportError:
            subprocess.check_call([sys.executable, '-m', 'pip', 'install', '-q', pipname])
    bad = [p for p in (TEST_IMG, TEST_LBL) if not os.path.isdir(p)]
    assert not bad, f'Missing folders (is BASE_DIR right? currently {BASE_DIR}): {bad}'
    miss = [f'{n}: {ck}' for n, (_, ck) in MODELS.items() if not os.path.exists(ck)]
    if miss:
        print('WARNING - checkpoints not found (these models will be skipped):\n  ' + '\n  '.join(miss))


def main():
    ap = argparse.ArgumentParser(); ap.add_argument('--selftest', action='store_true')
    ap.add_argument('--refresh', action='store_true'); a, _ = ap.parse_known_args()   # ignore Colab's -f kernel arg
    if a.selftest:
        return selftest()
    import pickle
    colab_setup()
    os.makedirs(OUT_DIR, exist_ok=True)
    imgs = list_images(TEST_IMG); stems = [os.path.splitext(os.path.basename(p))[0] for p in imgs]
    gts = load_gts(imgs, TEST_LBL)
    print(f'{len(imgs)} test images, {sum(len(g["cls"]) for g in gts.values())} GT lesions')
    preds = {}
    for name, (kind, ck) in MODELS.items():
        cache = f'{OUT_DIR}/_pred_{name.replace(" ", "_")}.pkl'
        if os.path.exists(cache) and not a.refresh:
            preds[name] = pickle.load(open(cache, 'rb')); print('cached ', name); continue
        if not os.path.exists(ck):
            print('MISSING', name, ck); continue
        print('infer  ', name); preds[name] = predict_model(kind, ck, imgs)
        pickle.dump(preds[name], open(cache, 'wb'))
    miss = [m for m in ENSEMBLE['members'] + [BASELINE] if m not in preds]
    assert not miss, f'ensemble/baseline members missing: {miss}'
    preds[ENSEMBLE['name']] = wbf_fuse(preds, gts, ENSEMBLE['members'], ENSEMBLE['weights'],
                                       ENSEMBLE['iou_thr'], ENSEMBLE['skip_box_thr'])
    dump_predictions(preds, gts, stems, OUT_DIR)
    t23, t6, t7, tf, cfg = analyze(preds, gts, stems, OUT_DIR, ENSEMBLE['name'], BASELINE)
    pd.set_option('display.width', 250); pd.set_option('display.max_columns', 30)
    print('\n=== TABLE 2/3 (unified) ===\n', t23.to_string(index=False))
    print('\n=== TABLE 6 (class-wise, with FP/image) ===\n',
          t6[t6.Model.isin([BASELINE, ENSEMBLE['name']])].to_string(index=False))
    print('\n=== TABLE 7 (paired bootstrap) ===\n', t7.to_string(index=False))
    print('\n=== FROC: sensitivity at fixed FP/image ===\n', tf.to_string(index=False))
    print('\n=== METHODS TEXT (paste into Section 2.5) ===\n' + methods_text(cfg))
    print('\nAll files in', OUT_DIR)


if __name__ == '__main__':
    main()

import sys, subprocess, warnings
