import torch
warnings.filterwarnings('ignore')
from torchvision.models.detection import fasterrcnn_resnet50_fpn_v2
from fvcore.nn import FlopCountAnalysis

NC = 2                      # dentin, enamel
CKPT = '/content/drive/MyDrive/CR1/CariesDet_Scaling/FasterRCNN/best.pth'   # optional; FLOPs do not depend on weights

model = fasterrcnn_resnet50_fpn_v2(weights=None, num_classes=NC + 1)
try:
    st = torch.load(CKPT, map_location='cpu')
    if isinstance(st, dict) and not any(k.startswith(('backbone', 'rpn', 'roi_heads')) for k in st):
        st = st.get('model', st.get('state_dict', st))
    model.load_state_dict(st); print('checkpoint loaded')
except Exception as e:
    print('checkpoint not loaded (not needed for FLOPs):', e)
model.eval()
params = sum(p.numel() for p in model.parameters()) / 1e6
print(f'Params: {params:.2f} M')

class Wrap(torch.nn.Module):             # fvcore needs tensor outputs
    def __init__(s, m): super().__init__(); s.m = m
    def forward(s, x):
        o = s.m([x[0]])[0]
        return o['boxes'], o['scores'], o['labels']

for H in (640,):                         # test images are 640x640; torchvision resizes internally (min_size=800)
    x = torch.rand(1, 3, H, H)
    with torch.no_grad():
        fl = FlopCountAnalysis(Wrap(model), (x,))
        fl.unsupported_ops_warnings(False); fl.uncalled_modules_warnings(False)
        macs = fl.total()
    print(f'Input {H}x{H} (internally resized to 800x800):')
    print(f'  multiply-accumulates : {macs/1e9:.1f} G')
    print(f'  GFLOPs (2 x MACs, same convention as Ultralytics): {2*macs/1e9:.1f}')

import os, sys, glob, json, pickle, itertools, subprocess, importlib
import numpy as np
import pandas as pd

# ─────────────────────────────── CONFIG (edit here) ───────────────────────────────
BASE_DIR = os.environ.get('CARIES_BASE', '/content/drive/MyDrive/CR1')
TEST_IMG = f'{BASE_DIR}/test/images'
TEST_LBL = f'{BASE_DIR}/test/labels'
VAL_IMG  = f'{BASE_DIR}/valid/images'          # change to 'val' if that is your folder name
VAL_LBL  = f'{BASE_DIR}/valid/labels'
RUNS     = f'{BASE_DIR}/CariesDet_Scaling'
OUT_DIR  = f'{RUNS}/Reconciled'
OUT      = f'{OUT_DIR}/extra_ensembles'
WEIGHTS_JSON = f'{OUT_DIR}/weights_frozen.json'

CLASS_NAMES = ['dentin-caries', 'enamel-caries']
NC = len(CLASS_NAMES)

MODELS = {   # name -> (kind, checkpoint)
    'YOLOv11s':  ('yolo',   f'{RUNS}/CariesDet_yolo11s/weights/best.pt'),
    'YOLOv8s':   ('yolo',   f'{RUNS}/CariesDet_YOLOv8s/weights/best.pt'),
    'YOLOv8m':   ('yolo',   f'{RUNS}/CariesDet_YOLOv8m/weights/best.pt'),
    'YOLOv10s':  ('yolo',   f'{RUNS}/CariesDet_YOLOv10s/weights/best.pt'),
    'RT-DETR-L': ('rtdetr', f'{RUNS}/CariesDet_RT-DETR-L/weights/best.pt'),
}

ENS = {
    'YOLOv8s + YOLOv11s': dict(members=['YOLOv8s', 'YOLOv11s'], weights=[0.51, 0.49]),  # your reported one
    'YOLOv8s + YOLOv10s': dict(members=['YOLOv8s', 'YOLOv10s'], weights=None),          # None = tune on val
    '5-model WBF':        dict(members=['RT-DETR-L', 'YOLOv8s', 'YOLOv8m', 'YOLOv11s', 'YOLOv10s'],
                               weights=None),
}
REF, BASE = 'YOLOv8s + YOLOv11s', 'YOLOv8s'
GRID_LEVELS = (1, 2, 3)                          # 3^5 = 243 weight combos for the 5-model ensemble
IOU_THR, SKIP_THR = 0.50, 0.001

CONF_OP, IOU_MATCH = 0.25, 0.50
PRED_CONF, PRED_NMS_IOU, IMGSZ = 0.001, 0.70, 640
N_BOOT, SEED = 1000, 42
FPI_GRID = [0.25, 0.5, 1.0, 2.0]
IOUS = np.round(np.arange(0.5, 0.96, 0.05), 2)

# ─────────────────────────────── SETUP ───────────────────────────────
def setup():
    try:
        from google.colab import drive
        if not os.path.isdir('/content/drive/MyDrive'):
            drive.mount('/content/drive')
    except ImportError:
        pass
    for mod, pipname in (('ultralytics', 'ultralytics'), ('ensemble_boxes', 'ensemble-boxes')):
        try:
            importlib.import_module(mod)
        except ImportError:
            subprocess.check_call([sys.executable, '-m', 'pip', 'install', '-q', pipname])
    bad = [p for p in (TEST_IMG, TEST_LBL) if not os.path.isdir(p)]
    assert not bad, f'Missing folders (is BASE_DIR right? currently {BASE_DIR}): {bad}'

# ─────────────────────────────── DATA / INFERENCE ───────────────────────────────
def list_images(d):
    ps = []
    for e in ('*.jpg', '*.jpeg', '*.png', '*.bmp'):
        ps += glob.glob(os.path.join(d, e))
    return sorted(ps)


def load_gts(img_paths, lbl_dir):
    from PIL import Image
    gts = {}
    for p in img_paths:
        stem = os.path.splitext(os.path.basename(p))[0]
        W, H = Image.open(p).size
        b, c = [], []
        lp = os.path.join(lbl_dir, stem + '.txt')
        if os.path.exists(lp):
            for line in open(lp):
                t = line.split()
                if len(t) < 5:
                    continue
                k, cx, cy, bw, bh = int(float(t[0])), *map(float, t[1:5])
                b.append([(cx - bw / 2) * W, (cy - bh / 2) * H, (cx + bw / 2) * W, (cy + bh / 2) * H])
                c.append(k)
        gts[stem] = dict(boxes=np.array(b, float).reshape(-1, 4), cls=np.array(c, int), w=W, h=H)
    return gts


def predict_model(kind, ckpt, img_paths):
    from ultralytics import YOLO, RTDETR
    out = {}
    model = (RTDETR if kind == 'rtdetr' else YOLO)(ckpt)
    for p in img_paths:
        r = model.predict(p, conf=PRED_CONF, iou=PRED_NMS_IOU, imgsz=IMGSZ, max_det=300, verbose=False)[0]
        stem = os.path.splitext(os.path.basename(p))[0]
        if r.boxes is None or len(r.boxes) == 0:
            out[stem] = (np.zeros((0, 4)), np.zeros(0), np.zeros(0, int))
        else:
            out[stem] = (r.boxes.xyxy.cpu().numpy().astype(float),
                         r.boxes.conf.cpu().numpy().astype(float),
                         r.boxes.cls.cpu().numpy().astype(int))
    return out


def cached_pred(name, imgs, prefix):
    """prefix '_pred_' = test (same cache as reconcile_tables.py), '_valpred_' = validation."""
    f = f'{OUT_DIR}/{prefix}{name.replace(" ", "_")}.pkl'
    if os.path.exists(f):
        print('cached ', prefix, name)
        return pickle.load(open(f, 'rb'))
    kind, ck = MODELS[name]
    assert os.path.exists(ck), f'Checkpoint not found for {name}: {ck}'
    print('infer  ', prefix, name)
    p = predict_model(kind, ck, imgs)
    pickle.dump(p, open(f, 'wb'))
    return p


def wbf_fuse(preds, gts, members, weights, iou_thr, skip_thr):
    from ensemble_boxes import weighted_boxes_fusion
    out = {}
    for stem, g in gts.items():
        sc = np.array([g['w'], g['h'], g['w'], g['h']], float)
        bl, sl, ll = [], [], []
        for m in members:
            b, s, c = preds[m][stem]
            bl.append(np.clip(b / sc, 0, 1).tolist() if len(s) else [])
            sl.append(s.tolist()); ll.append(c.tolist())
        if all(len(s) == 0 for s in sl):
            out[stem] = (np.zeros((0, 4)), np.zeros(0), np.zeros(0, int)); continue
        fb, fs, fl = weighted_boxes_fusion(bl, sl, ll, weights=weights, iou_thr=iou_thr, skip_box_thr=skip_thr)
        out[stem] = (np.asarray(fb).reshape(-1, 4) * sc, np.asarray(fs), np.asarray(fl).astype(int))
    return out

# ─────────────────────────────── MATCHING / METRICS (identical to reconcile_tables.py) ──────────
def iou_matrix(a, b):
    a = np.asarray(a, float).reshape(-1, 4); b = np.asarray(b, float).reshape(-1, 4)
    ix1 = np.maximum(a[:, None, 0], b[None, :, 0]); iy1 = np.maximum(a[:, None, 1], b[None, :, 1])
    ix2 = np.minimum(a[:, None, 2], b[None, :, 2]); iy2 = np.minimum(a[:, None, 3], b[None, :, 3])
    inter = np.clip(ix2 - ix1, 0, None) * np.clip(iy2 - iy1, 0, None)
    aa = (a[:, 2] - a[:, 0]) * (a[:, 3] - a[:, 1]); ab = (b[:, 2] - b[:, 0]) * (b[:, 3] - b[:, 1])
    return inter / (aa[:, None] + ab[None, :] - inter + 1e-9)


def match_image(pb, ps, pc, gb, gc, thr):
    tp = np.zeros(len(ps), bool)
    if len(ps) == 0 or len(gb) == 0:
        return tp
    ious = iou_matrix(pb, gb); used = np.zeros(len(gb), bool)
    for i in np.argsort(-ps, kind='stable'):
        cand = np.where((gc == pc[i]) & ~used)[0]
        if len(cand) == 0:
            continue
        j = cand[np.argmax(ious[i, cand])]
        if ious[i, j] >= thr:
            tp[i] = True; used[j] = True
    return tp


_trapz = getattr(np, 'trapezoid', None) or np.trapz


def ap101(tp, wts, ngt):
    if ngt <= 0:
        return np.nan
    tpc = np.cumsum(wts * tp); fpc = np.cumsum(wts * (~tp))
    rec = tpc / ngt; prec = tpc / np.maximum(tpc + fpc, 1e-12)
    mrec = np.concatenate(([0.], rec, [1.])); mpre = np.concatenate(([1.], prec, [0.]))
    mpre = np.flip(np.maximum.accumulate(np.flip(mpre)))
    x = np.linspace(0, 1, 101)
    return float(_trapz(np.interp(x, mrec, mpre), x))


class Dets:
    def __init__(self, pred, gts, stems, ious=IOUS):
        self.n_img = len(stems); self.ious = ious
        self.n_gt = np.zeros((self.n_img, NC))
        per = {c: ([], [], []) for c in range(NC)}
        for k, stem in enumerate(stems):
            g = gts[stem]
            for c in range(NC):
                self.n_gt[k, c] = (g['cls'] == c).sum()
            b, s, c_ = pred[stem]
            if len(s) == 0:
                continue
            tp = np.stack([match_image(b, s, c_, g['boxes'], g['cls'], t) for t in ious], 1)
            for c in range(NC):
                m = c_ == c
                per[c][0].append(s[m]); per[c][1].append(np.full(m.sum(), k)); per[c][2].append(tp[m])
        self.cls_d = {}
        for c in range(NC):
            s = np.concatenate(per[c][0]) if per[c][0] else np.zeros(0)
            i = np.concatenate(per[c][1]) if per[c][1] else np.zeros(0, int)
            t = np.concatenate(per[c][2]) if per[c][2] else np.zeros((0, len(ious)), bool)
            o = np.argsort(-s, kind='stable')
            self.cls_d[c] = (s[o], i[o], t[o])


def metrics(d, w=None, full=False):
    w = np.ones(d.n_img) if w is None else w
    gtw = (w[:, None] * d.n_gt).sum(0)
    res = {'cls': {}}; TP = FP = FN = 0.0; ap50, ap_all = [], []
    for c in range(NC):
        s, i, t = d.cls_d[c]; dw = w[i]; k = s >= CONF_OP
        tp = float((dw[k] * t[k, 0]).sum()); fp = float((dw[k] * (~t[k, 0])).sum()); fn = float(gtw[c] - tp)
        TP += tp; FP += fp; FN += fn
        p = tp / (tp + fp) if tp + fp > 0 else 0.0; r = tp / (tp + fn) if tp + fn > 0 else 0.0
        res['cls'][c] = dict(TP=tp, FP=fp, FN=fn, P=p, R=r, F1=2 * p * r / (p + r) if p + r > 0 else 0.0,
                             FPI=fp / w.sum(), AP50=ap101(t[:, 0], dw, gtw[c]))
        ap50.append(res['cls'][c]['AP50'])
        if full:
            ap_all.append([ap101(t[:, j], dw, gtw[c]) for j in range(t.shape[1])])
    P = TP / (TP + FP) if TP + FP > 0 else 0.0; R = TP / (TP + FN) if TP + FN > 0 else 0.0
    res.update(TP=TP, FP=FP, FN=FN, P=P, R=R, F1=2 * P * R / (P + R) if P + R > 0 else 0.0,
               FPI=FP / w.sum(), mAP50=float(np.nanmean(ap50)))
    if full:
        res['mAP50_95'] = float(np.nanmean(np.array(ap_all)))
    return res


def froc(d, cls=None):
    cs = list(range(NC)) if cls is None else [cls]
    s = np.concatenate([d.cls_d[c][0] for c in cs]); t = np.concatenate([d.cls_d[c][2][:, 0] for c in cs])
    o = np.argsort(-s, kind='stable'); t = t[o]
    return np.cumsum(~t) / d.n_img, np.cumsum(t) / d.n_gt[:, cs].sum()


def sens_at(fpi, sens, x):
    m = fpi <= x
    return float(sens[m].max()) if m.any() else 0.0


def pct(a):
    return float(np.percentile(a, 2.5)), float(np.percentile(a, 97.5))

# ─────────────────────────────── WEIGHT TUNING (validation only) ───────────────────────────────
def tune_weights(members, vimgs, vstems, vgts):
    P = {m: cached_pred(m, vimgs, '_valpred_') for m in members}
    best_s, best_w = -1.0, None
    for w in itertools.product(GRID_LEVELS, repeat=len(members)):
        w = (np.array(w, float) / sum(w)).tolist()
        fused = wbf_fuse(P, vgts, members, w, IOU_THR, SKIP_THR)
        s = metrics(Dets(fused, vgts, vstems, ious=IOUS[:1]))['mAP50']   # IoU 0.50 only (fast)
        if s > best_s:
            best_s, best_w = s, w
    print(f'  {members}: val mAP50 = {best_s:.4f}, weights = {best_w}')
    return best_w


def resolve_weights():
    saved = json.load(open(WEIGHTS_JSON)) if os.path.exists(WEIGHTS_JSON) else {}
    for k, v in ENS.items():
        if v['weights'] is None and k in saved:
            v['weights'] = saved[k]
    need = [k for k, v in ENS.items() if v['weights'] is None]
    if need:
        assert os.path.isdir(VAL_IMG), f'Validation folder not found: {VAL_IMG}'
        vimgs = list_images(VAL_IMG)
        vstems = [os.path.splitext(os.path.basename(p))[0] for p in vimgs]
        vgts = load_gts(vimgs, VAL_LBL)
        print(f'Tuning on {len(vimgs)} validation images')
        for k in need:
            ENS[k]['weights'] = tune_weights(ENS[k]['members'], vimgs, vstems, vgts)
            saved[k] = ENS[k]['weights']
        json.dump(saved, open(WEIGHTS_JSON, 'w'), indent=2)
    print('FROZEN WEIGHTS:', json.dumps({k: v['weights'] for k, v in ENS.items()}))

# ─────────────────────────────── MAIN ───────────────────────────────
def main():
    setup()
    os.makedirs(OUT, exist_ok=True)
    resolve_weights()

    imgs = list_images(TEST_IMG)
    stems = [os.path.splitext(os.path.basename(p))[0] for p in imgs]
    gts = load_gts(imgs, TEST_LBL)
    n = len(stems)
    print(f'{n} test images, {sum(len(g["cls"]) for g in gts.values())} GT lesions')

    need = {BASE} | {m for v in ENS.values() for m in v['members']}
    preds = {m: cached_pred(m, imgs, '_pred_') for m in need}
    for name, v in ENS.items():
        preds[name] = wbf_fuse(preds, gts, v['members'], v['weights'], IOU_THR, SKIP_THR)

    names = [BASE] + list(ENS.keys())
    D = {m: Dets(preds[m], gts, stems) for m in names}

    rng = np.random.default_rng(SEED)                    # same resamples as reconcile_tables.py
    IDX = rng.integers(0, n, (N_BOOT, n))
    WB = np.stack([np.bincount(r, minlength=n) for r in IDX]).astype(float)

    pt, boot = {}, {}
    for m in names:
        pt[m] = metrics(D[m], full=True)
        rep = [metrics(D[m], WB[b]) for b in range(N_BOOT)]
        boot[m] = {k: np.array([r[k] for r in rep]) for k in ('P', 'R', 'F1', 'mAP50', 'FPI')}

    rows = []
    for m in names:
        r = pt[m]; row = {'Model': m}
        for lab, key in (('Precision', 'P'), ('Recall', 'R'), ('F1', 'F1'), ('mAP@0.50', 'mAP50')):
            lo, hi = pct(boot[m][key]); row[lab] = round(r[key], 4); row[lab + ' 95% CI'] = f'{lo:.4f}-{hi:.4f}'
        row['mAP@0.50:0.95'] = round(r['mAP50_95'], 4)
        row.update(TP=int(r['TP']), FP=int(r['FP']), FN=int(r['FN']), **{'FP/image': round(r['FPI'], 3)})
        rows.append(row)
    t = pd.DataFrame(rows); t.to_csv(f'{OUT}/ensembles_unified.csv', index=False)

    prow = []
    for name in ENS:
        for ref in (BASE, REF):
            if name == ref:
                continue
            for lab, key in (('mAP@0.50', 'mAP50'), ('Precision', 'P'), ('Recall', 'R'),
                             ('F1', 'F1'), ('FP/image', 'FPI')):
                d = boot[name][key] - boot[ref][key]; lo, hi = pct(d)
                prow.append({'Ensemble': name, 'Versus': ref, 'Metric': lab,
                             'Point difference': round(pt[name][key] - pt[ref][key], 4),
                             'Bootstrap mean difference': round(float(d.mean()), 4),
                             '95% interval': f'{lo:+.4f} to {hi:+.4f}'})
    pp = pd.DataFrame(prow); pp.to_csv(f'{OUT}/ensembles_paired.csv', index=False)

    frows = []
    for m in names:
        f, s = froc(D[m])
        frows.append({'Model': m, **{f'Sens @ <= {x} FP/img': round(sens_at(f, s, x), 4) for x in FPI_GRID}})
    tf = pd.DataFrame(frows); tf.to_csv(f'{OUT}/ensembles_froc_sensitivity.csv', index=False)

    import matplotlib; matplotlib.use('Agg'); import matplotlib.pyplot as plt
    fig, ax = plt.subplots(figsize=(6.5, 4.8))
    for m in names:
        f, s = froc(D[m]); ax.step(f, s, where='post', label=m)
    ax.set_xlim(0, 3); ax.set_ylim(0, 1.02); ax.set_xlabel('False positives per image')
    ax.set_ylabel('Sensitivity'); ax.grid(alpha=.3); ax.legend(fontsize=8); ax.set_title('FROC - test set (overall)')
    fig.tight_layout(); fig.savefig(f'{OUT}/froc_ensembles.png', dpi=300); plt.close(fig)

    groups = list(ENS.keys())
    labels = {g: f"{g}\n(N={len(ENS[g]['members'])})" for g in groups}
    cols = {'P': '#5b7fb8', 'R': '#5fb374', 'F1': '#cc5c5c'}; nm = {'P': 'Precision', 'R': 'Recall', 'F1': 'F1'}
    w = 0.25; x = np.arange(len(groups))
    fig, ax = plt.subplots(figsize=(10, 5.8), dpi=200)
    for k, key in enumerate(['P', 'R', 'F1']):
        off = (k - 1) * w
        v = np.array([[pt[g][key], *pct(boot[g][key])] for g in groups])
        ax.bar(x + off, v[:, 0], w, color=cols[key], alpha=0.9, edgecolor='black', lw=0.7, label=nm[key])
        ax.errorbar(x + off, v[:, 0], yerr=[v[:, 0] - v[:, 1], v[:, 2] - v[:, 0]], fmt='none',
                    ecolor='black', capsize=5, lw=1.6)
        for xi, hi, p in zip(x + off, v[:, 2], v[:, 0]):
            ax.text(xi, hi + 0.015, f'{p:.3f}', ha='center', va='bottom', fontsize=9, fontweight='bold')
    for xi, g in zip(x, groups):
        ax.plot(xi, pt[g]['mAP50'], marker='D', color='black', ms=9, ls='none', zorder=5)
    ax.plot([], [], marker='D', color='black', ms=9, ls='none', label='mAP@0.50 (point estimate)')
    ax.set_xticks(x)
    ax.set_xticklabels([f"{labels[g]}\nmAP@0.50 = {pt[g]['mAP50']:.3f}" for g in groups], fontsize=11)
    ax.set_ylim(0, 1.12); ax.set_ylabel('Score', fontsize=13)
    ax.grid(axis='y', ls='--', alpha=0.35); ax.set_axisbelow(True)
    for s_ in ('top', 'right'): ax.spines[s_].set_visible(False)
    ax.set_title('WBF Ensemble Comparison - Test Set\nPrecision / Recall / F1 '
                 f'(point estimate, 95% bootstrap CI, n_boot = {N_BOOT})', fontsize=12.5, fontweight='bold')
    ax.legend(loc='upper center', bbox_to_anchor=(0.5, -0.19), ncol=4, frameon=False, fontsize=10)
    fig.text(0.5, 0.012, f'P/R/F1 at confidence >= {CONF_OP}, IoU >= {IOU_MATCH} (micro-averaged); '
             'mAP@0.50 from all predictions.\nWBF IoU = 0.50; weights frozen from validation set.',
             ha='center', fontsize=8, style='italic', color='#444')
    fig.tight_layout(rect=(0, 0.06, 1, 1)); fig.savefig(f'{OUT}/fig5_three_candidates.png'); plt.close(fig)

    pd.set_option('display.width', 250); pd.set_option('display.max_columns', 30)
    print('\n=== CHECK FIRST: this row must equal P 0.9286, R 0.6393, F1 0.7573, mAP 0.8490, TP 78 FP 6 FN 44 ===')
    print(t[t.Model == REF].to_string(index=False))
    print('\n=== UNIFIED TABLE ===\n', t.to_string(index=False))
    print('\n=== PAIRED BOOTSTRAP ===\n', pp.to_string(index=False))
    print('\n=== FROC SENSITIVITY AT MATCHED FP/IMAGE ===\n', tf.to_string(index=False))
    print('\nSaved to', OUT)


main()

import os, sys
import numpy as np, pandas as pd
import matplotlib; matplotlib.use("Agg")
import matplotlib.pyplot as plt

RUNS = os.environ.get("CARIES_RUNS", "/content/drive/MyDrive/CR1/CariesDet_Scaling")
_args = [a for a in sys.argv[1:] if a.lower().endswith(".csv")]      # ignores Jupyter/Colab's "-f kernel.json"
CSV = {
    "YOLOv8s":  _args[0] if len(_args) >= 2 else f"{RUNS}/CariesDet_YOLOv8s/results.csv",
    "YOLOv11s": _args[1] if len(_args) >= 2 else f"{RUNS}/CariesDet_yolo11s/results.csv",   # label corrected: YOLOv11s
}
for _n, _p in CSV.items():
    if not os.path.exists(_p):
        raise FileNotFoundError(f"{_n} results.csv not found at: {_p}\n"
                                f"Edit RUNS / the folder names above, or set CSV[...] to the right path.")
COLOR = {"YOLOv8s": "#dd8452", "YOLOv11s": "#4c72b0"}
SUPTITLE = "Validation Performance and Train/Val Loss over Training"   # add "Figure 6. " here only if the number is NOT in the manuscript caption
OUT = "training_curves_YOLOv8s_YOLOv11s.png"

METRICS = [("metrics/precision(B)", "Precision (val)", "-"),
           ("metrics/recall(B)",    "Recall (val)",    "--"),
           ("metrics/mAP50(B)",     "mAP50 (val)",     "-."),
           ("metrics/mAP50-95(B)",  "mAP50-95 (val)",  ":")]

def load(p):
    df = pd.read_csv(p); df.columns = [c.strip() for c in df.columns]; return df

fig, axs = plt.subplots(2, 2, figsize=(12.5, 9), dpi=200)
for j, (name, path) in enumerate(CSV.items()):
    df = load(path); ep = df["epoch"].to_numpy()
    if ep.min() == 0: ep = ep + 1                       # Ultralytics logs epochs from 0 or 1 depending on version
    ax = axs[0, j]
    for col, lab, ls in METRICS:
        ax.plot(ep, df[col], ls=ls, lw=1.8, color=COLOR[name], label=lab)
    ax.set_title(f"{name} — Validation Metrics by Epoch", fontsize=12, fontweight="bold")
    ax.set_xlabel("Epoch"); ax.set_ylabel("Score"); ax.set_ylim(0, 1.0)
    ax.legend(loc="upper left", fontsize=8, frameon=False)
    ax = axs[1, j]
    ax.plot(ep, df["train/box_loss"], color="#55a868", lw=1.8, label="Train box loss")
    ax.plot(ep, df["val/box_loss"],   color="#c44e52", lw=1.8, label="Val box loss")
    ax.set_title(f"{name} — Train vs. Val Loss", fontsize=12, fontweight="bold")
    ax.set_xlabel("Epoch"); ax.set_ylabel("Box loss"); ax.legend(loc="upper right", fontsize=8, frameon=False)
for ax in axs.ravel():
    ax.grid(ls=":", alpha=0.4); ax.set_axisbelow(True)
    for s in ("top", "right"): ax.spines[s].set_visible(False)
fig.suptitle(SUPTITLE, fontsize=14, fontweight="bold")
fig.tight_layout(rect=(0, 0, 1, 0.96)); fig.savefig(OUT); print("saved", OUT)



# -*- coding: utf-8 -*-
"""
ensemble_val_froc.py  -  (1) VALIDATION metrics for YOLOv8s+YOLOv11s (and YOLOv8s+YOLOv10s);
(2) test-set FROC sensitivity at matched FP/image for YOLOv8s vs YOLOv8s+YOLOv10s vs YOLOv8s+YOLOv11s
    (overall / dentin / enamel) with paired bootstrap CIs.

Computes with the SAME evaluation convention as reconcile_tables.py:
    * YOLOv8s + YOLOv11s   (reference; must reproduce P 0.9286 R 0.6393 F1 0.7573 TP 78 FP 6 FN 44)
    * YOLOv8s + YOLOv10s
    * 5-model WBF (RT-DETR-L, YOLOv8s, YOLOv8m, YOLOv11s, YOLOv10s)

Weights: any ensemble whose weights are None is tuned on the VALIDATION set (val mAP@0.50,
threshold-free) and saved to weights_frozen.json (next runs reuse it = frozen).
Test predictions: reused from Reconciled/_pred_*.pkl if present (written by reconcile_tables.py),
otherwise inference is run here and cached under the same names.

Colab:  paste into one cell and run, or  %run full_ensembles_standalone.py
"""
import os, sys, glob, json, pickle, itertools, subprocess, importlib
import numpy as np
import pandas as pd

# ─────────────────────────────── CONFIG (edit here) ───────────────────────────────
BASE_DIR = os.environ.get('CARIES_BASE', '/content/drive/MyDrive/CR1')
TEST_IMG = f'{BASE_DIR}/test/images'
TEST_LBL = f'{BASE_DIR}/test/labels'
VAL_IMG  = f'{BASE_DIR}/valid/images'          # change to 'val' if that is your folder name
VAL_LBL  = f'{BASE_DIR}/valid/labels'
RUNS     = f'{BASE_DIR}/CariesDet_Scaling'
OUT_DIR  = f'{RUNS}/Reconciled'
OUT      = f'{OUT_DIR}/val_froc_outputs'
WEIGHTS_JSON = f'{OUT_DIR}/weights_frozen.json'

CLASS_NAMES = ['dentin-caries', 'enamel-caries']
NC = len(CLASS_NAMES)

MODELS = {   # name -> (kind, checkpoint)
    'YOLOv11s':  ('yolo',   f'{RUNS}/CariesDet_yolo11s/weights/best.pt'),
    'YOLOv8s':   ('yolo',   f'{RUNS}/CariesDet_YOLOv8s/weights/best.pt'),
    'YOLOv8m':   ('yolo',   f'{RUNS}/CariesDet_YOLOv8m/weights/best.pt'),
    'YOLOv10s':  ('yolo',   f'{RUNS}/CariesDet_YOLOv10s/weights/best.pt'),
    'RT-DETR-L': ('rtdetr', f'{RUNS}/CariesDet_RT-DETR-L/weights/best.pt'),
}

ENS = {   # weights None = tune on VALIDATION (reuse weights_frozen.json if the key is already there)
    'YOLOv8s + YOLOv11s': dict(members=['YOLOv8s', 'YOLOv11s'], weights=None),
    'YOLOv8s + YOLOv10s': dict(members=['YOLOv8s', 'YOLOv10s'], weights=None),
}
REF, BASE = 'YOLOv8s + YOLOv11s', 'YOLOv8s'
GRID_LEVELS = (1, 2, 3)                          # 3^5 = 243 weight combos for the 5-model ensemble
IOU_THR, SKIP_THR = 0.50, 0.001

CONF_OP, IOU_MATCH = 0.25, 0.50
PRED_CONF, PRED_NMS_IOU, IMGSZ = 0.001, 0.70, 640
N_BOOT, SEED = 1000, 42
FPI_GRID = [0.25, 0.5, 1.0, 2.0]
IOUS = np.round(np.arange(0.5, 0.96, 0.05), 2)

# ─────────────────────────────── SETUP ───────────────────────────────
def setup():
    try:
        from google.colab import drive
        if not os.path.isdir('/content/drive/MyDrive'):
            drive.mount('/content/drive')
    except ImportError:
        pass
    for mod, pipname in (('ultralytics', 'ultralytics'), ('ensemble_boxes', 'ensemble-boxes')):
        try:
            importlib.import_module(mod)
        except ImportError:
            subprocess.check_call([sys.executable, '-m', 'pip', 'install', '-q', pipname])
    bad = [p for p in (TEST_IMG, TEST_LBL) if not os.path.isdir(p)]
    assert not bad, f'Missing folders (is BASE_DIR right? currently {BASE_DIR}): {bad}'

# ─────────────────────────────── DATA / INFERENCE ───────────────────────────────
def list_images(d):
    ps = []
    for e in ('*.jpg', '*.jpeg', '*.png', '*.bmp'):
        ps += glob.glob(os.path.join(d, e))
    return sorted(ps)


def load_gts(img_paths, lbl_dir):
    from PIL import Image
    gts = {}
    for p in img_paths:
        stem = os.path.splitext(os.path.basename(p))[0]
        W, H = Image.open(p).size
        b, c = [], []
        lp = os.path.join(lbl_dir, stem + '.txt')
        if os.path.exists(lp):
            for line in open(lp):
                t = line.split()
                if len(t) < 5:
                    continue
                k, cx, cy, bw, bh = int(float(t[0])), *map(float, t[1:5])
                b.append([(cx - bw / 2) * W, (cy - bh / 2) * H, (cx + bw / 2) * W, (cy + bh / 2) * H])
                c.append(k)
        gts[stem] = dict(boxes=np.array(b, float).reshape(-1, 4), cls=np.array(c, int), w=W, h=H)
    return gts


def predict_model(kind, ckpt, img_paths):
    from ultralytics import YOLO, RTDETR
    out = {}
    model = (RTDETR if kind == 'rtdetr' else YOLO)(ckpt)
    for p in img_paths:
        r = model.predict(p, conf=PRED_CONF, iou=PRED_NMS_IOU, imgsz=IMGSZ, max_det=300, verbose=False)[0]
        stem = os.path.splitext(os.path.basename(p))[0]
        if r.boxes is None or len(r.boxes) == 0:
            out[stem] = (np.zeros((0, 4)), np.zeros(0), np.zeros(0, int))
        else:
            out[stem] = (r.boxes.xyxy.cpu().numpy().astype(float),
                         r.boxes.conf.cpu().numpy().astype(float),
                         r.boxes.cls.cpu().numpy().astype(int))
    return out


def cached_pred(name, imgs, prefix):
    """prefix '_pred_' = test (same cache as reconcile_tables.py), '_valpred_' = validation."""
    f = f'{OUT_DIR}/{prefix}{name.replace(" ", "_")}.pkl'
    if os.path.exists(f):
        print('cached ', prefix, name)
        return pickle.load(open(f, 'rb'))
    kind, ck = MODELS[name]
    assert os.path.exists(ck), f'Checkpoint not found for {name}: {ck}'
    print('infer  ', prefix, name)
    p = predict_model(kind, ck, imgs)
    pickle.dump(p, open(f, 'wb'))
    return p


def wbf_fuse(preds, gts, members, weights, iou_thr, skip_thr):
    from ensemble_boxes import weighted_boxes_fusion
    out = {}
    for stem, g in gts.items():
        sc = np.array([g['w'], g['h'], g['w'], g['h']], float)
        bl, sl, ll = [], [], []
        for m in members:
            b, s, c = preds[m][stem]
            bl.append(np.clip(b / sc, 0, 1).tolist() if len(s) else [])
            sl.append(s.tolist()); ll.append(c.tolist())
        if all(len(s) == 0 for s in sl):
            out[stem] = (np.zeros((0, 4)), np.zeros(0), np.zeros(0, int)); continue
        fb, fs, fl = weighted_boxes_fusion(bl, sl, ll, weights=weights, iou_thr=iou_thr, skip_box_thr=skip_thr)
        out[stem] = (np.asarray(fb).reshape(-1, 4) * sc, np.asarray(fs), np.asarray(fl).astype(int))
    return out

# ─────────────────────────────── MATCHING / METRICS (identical to reconcile_tables.py) ──────────
def iou_matrix(a, b):
    a = np.asarray(a, float).reshape(-1, 4); b = np.asarray(b, float).reshape(-1, 4)
    ix1 = np.maximum(a[:, None, 0], b[None, :, 0]); iy1 = np.maximum(a[:, None, 1], b[None, :, 1])
    ix2 = np.minimum(a[:, None, 2], b[None, :, 2]); iy2 = np.minimum(a[:, None, 3], b[None, :, 3])
    inter = np.clip(ix2 - ix1, 0, None) * np.clip(iy2 - iy1, 0, None)
    aa = (a[:, 2] - a[:, 0]) * (a[:, 3] - a[:, 1]); ab = (b[:, 2] - b[:, 0]) * (b[:, 3] - b[:, 1])
    return inter / (aa[:, None] + ab[None, :] - inter + 1e-9)


def match_image(pb, ps, pc, gb, gc, thr):
    tp = np.zeros(len(ps), bool)
    if len(ps) == 0 or len(gb) == 0:
        return tp
    ious = iou_matrix(pb, gb); used = np.zeros(len(gb), bool)
    for i in np.argsort(-ps, kind='stable'):
        cand = np.where((gc == pc[i]) & ~used)[0]
        if len(cand) == 0:
            continue
        j = cand[np.argmax(ious[i, cand])]
        if ious[i, j] >= thr:
            tp[i] = True; used[j] = True
    return tp


_trapz = getattr(np, 'trapezoid', None) or np.trapz


def ap101(tp, wts, ngt):
    if ngt <= 0:
        return np.nan
    tpc = np.cumsum(wts * tp); fpc = np.cumsum(wts * (~tp))
    rec = tpc / ngt; prec = tpc / np.maximum(tpc + fpc, 1e-12)
    mrec = np.concatenate(([0.], rec, [1.])); mpre = np.concatenate(([1.], prec, [0.]))
    mpre = np.flip(np.maximum.accumulate(np.flip(mpre)))
    x = np.linspace(0, 1, 101)
    return float(_trapz(np.interp(x, mrec, mpre), x))


class Dets:
    def __init__(self, pred, gts, stems, ious=IOUS):
        self.n_img = len(stems); self.ious = ious
        self.n_gt = np.zeros((self.n_img, NC))
        per = {c: ([], [], []) for c in range(NC)}
        for k, stem in enumerate(stems):
            g = gts[stem]
            for c in range(NC):
                self.n_gt[k, c] = (g['cls'] == c).sum()
            b, s, c_ = pred[stem]
            if len(s) == 0:
                continue
            tp = np.stack([match_image(b, s, c_, g['boxes'], g['cls'], t) for t in ious], 1)
            for c in range(NC):
                m = c_ == c
                per[c][0].append(s[m]); per[c][1].append(np.full(m.sum(), k)); per[c][2].append(tp[m])
        self.cls_d = {}
        for c in range(NC):
            s = np.concatenate(per[c][0]) if per[c][0] else np.zeros(0)
            i = np.concatenate(per[c][1]) if per[c][1] else np.zeros(0, int)
            t = np.concatenate(per[c][2]) if per[c][2] else np.zeros((0, len(ious)), bool)
            o = np.argsort(-s, kind='stable')
            self.cls_d[c] = (s[o], i[o], t[o])


def metrics(d, w=None, full=False):
    w = np.ones(d.n_img) if w is None else w
    gtw = (w[:, None] * d.n_gt).sum(0)
    res = {'cls': {}}; TP = FP = FN = 0.0; ap50, ap_all = [], []
    for c in range(NC):
        s, i, t = d.cls_d[c]; dw = w[i]; k = s >= CONF_OP
        tp = float((dw[k] * t[k, 0]).sum()); fp = float((dw[k] * (~t[k, 0])).sum()); fn = float(gtw[c] - tp)
        TP += tp; FP += fp; FN += fn
        p = tp / (tp + fp) if tp + fp > 0 else 0.0; r = tp / (tp + fn) if tp + fn > 0 else 0.0
        res['cls'][c] = dict(TP=tp, FP=fp, FN=fn, P=p, R=r, F1=2 * p * r / (p + r) if p + r > 0 else 0.0,
                             FPI=fp / w.sum(), AP50=ap101(t[:, 0], dw, gtw[c]))
        ap50.append(res['cls'][c]['AP50'])
        if full:
            ap_all.append([ap101(t[:, j], dw, gtw[c]) for j in range(t.shape[1])])
    P = TP / (TP + FP) if TP + FP > 0 else 0.0; R = TP / (TP + FN) if TP + FN > 0 else 0.0
    res.update(TP=TP, FP=FP, FN=FN, P=P, R=R, F1=2 * P * R / (P + R) if P + R > 0 else 0.0,
               FPI=FP / w.sum(), mAP50=float(np.nanmean(ap50)))
    if full:
        res['mAP50_95'] = float(np.nanmean(np.array(ap_all)))
    return res


def froc(d, cls=None):
    cs = list(range(NC)) if cls is None else [cls]
    s = np.concatenate([d.cls_d[c][0] for c in cs]); t = np.concatenate([d.cls_d[c][2][:, 0] for c in cs])
    o = np.argsort(-s, kind='stable'); t = t[o]
    return np.cumsum(~t) / d.n_img, np.cumsum(t) / d.n_gt[:, cs].sum()


def sens_at(fpi, sens, x):
    m = fpi <= x
    return float(sens[m].max()) if m.any() else 0.0


def pct(a):
    return float(np.percentile(a, 2.5)), float(np.percentile(a, 97.5))

# ─────────────────────────────── WEIGHT TUNING (validation only) ───────────────────────────────
def tune_weights(name, members, vimgs, vstems, vgts):
    P = {m: cached_pred(m, vimgs, '_valpred_') for m in members}
    best_s, best_w, log = -1.0, None, []
    for w in itertools.product(GRID_LEVELS, repeat=len(members)):
        w = (np.array(w, float) / sum(w)).tolist()
        fused = wbf_fuse(P, vgts, members, w, IOU_THR, SKIP_THR)
        s = metrics(Dets(fused, vgts, vstems, ious=IOUS[:1]))['mAP50']   # IoU 0.50 only (fast)
        log.append(dict(zip(members, np.round(w, 4)), val_mAP50=round(s, 4)))
        if s > best_s:
            best_s, best_w = s, w
    os.makedirs(OUT, exist_ok=True)
    pd.DataFrame(log).sort_values('val_mAP50', ascending=False).to_csv(
        f"{OUT}/val_weight_grid_{name.replace(' ', '')}.csv", index=False)
    print(f'  {members}: val mAP50 = {best_s:.4f}, weights = {best_w}')
    return best_w


def resolve_weights():
    saved = json.load(open(WEIGHTS_JSON)) if os.path.exists(WEIGHTS_JSON) else {}
    for k, v in ENS.items():
        if v['weights'] is None and k in saved:
            v['weights'] = saved[k]
    need = [k for k, v in ENS.items() if v['weights'] is None]
    if need:
        assert os.path.isdir(VAL_IMG), f'Validation folder not found: {VAL_IMG}'
        vimgs = list_images(VAL_IMG)
        vstems = [os.path.splitext(os.path.basename(p))[0] for p in vimgs]
        vgts = load_gts(vimgs, VAL_LBL)
        print(f'Tuning on {len(vimgs)} validation images')
        for k in need:
            ENS[k]['weights'] = tune_weights(k, ENS[k]['members'], vimgs, vstems, vgts)
            saved[k] = ENS[k]['weights']
        json.dump(saved, open(WEIGHTS_JSON, 'w'), indent=2)
    print('FROZEN WEIGHTS:', json.dumps({k: v['weights'] for k, v in ENS.items()}))

# ─────────────────────────────── VALIDATION REPORT ───────────────────────────────
def val_report():
    vimgs = list_images(VAL_IMG)
    vstems = [os.path.splitext(os.path.basename(p))[0] for p in vimgs]
    vgts = load_gts(vimgs, VAL_LBL)
    need = {BASE} | {m for v in ENS.values() for m in v['members']}
    P = {m: cached_pred(m, vimgs, '_valpred_') for m in need}
    for name, v in ENS.items():
        P[name] = wbf_fuse(P, vgts, v['members'], v['weights'], IOU_THR, SKIP_THR)
    names = sorted(need) + list(ENS.keys())
    rows = []
    for m in names:
        r = metrics(Dets(P[m], vgts, vstems), full=True)
        rows.append({'Model': m,
                     'Weights': dict(zip(ENS[m]['members'], np.round(ENS[m]['weights'], 3))) if m in ENS else '',
                     'val mAP@0.50': round(r['mAP50'], 4), 'val mAP@0.50:0.95': round(r['mAP50_95'], 4),
                     f'P@{CONF_OP}': round(r['P'], 4), f'R@{CONF_OP}': round(r['R'], 4),
                     f'F1@{CONF_OP}': round(r['F1'], 4), 'FP/image': round(r['FPI'], 3),
                     'dentin AP50': round(r['cls'][0]['AP50'], 4), 'enamel AP50': round(r['cls'][1]['AP50'], 4)})
    tv = pd.DataFrame(rows); tv.to_csv(f'{OUT}/validation_metrics.csv', index=False)
    print(f'\n=== VALIDATION SET ({len(vstems)} images) - weights tuned here, so these are NOT held-out ===')
    print(tv.to_string(index=False))

# ─────────────────────────────── WEIGHTED FROC (for paired bootstrap) ───────────────────────────────
def froc_w(d, w, cls=None):
    cs = list(range(NC)) if cls is None else [cls]
    s = np.concatenate([d.cls_d[c][0] for c in cs]); i = np.concatenate([d.cls_d[c][1] for c in cs])
    t = np.concatenate([d.cls_d[c][2][:, 0] for c in cs])
    o = np.argsort(-s, kind='stable'); dw = w[i[o]]; t = t[o]
    ngt = (w[:, None] * d.n_gt[:, cs]).sum()
    return np.cumsum(dw * (~t)) / w.sum(), np.cumsum(dw * t) / ngt

SCOPES = [('Overall', None), ('Dentin-caries', 0), ('Enamel-caries', 1)]

# ─────────────────────────────── MAIN ───────────────────────────────
def main():
    setup()
    os.makedirs(OUT, exist_ok=True)
    resolve_weights()
    val_report()

    imgs = list_images(TEST_IMG)
    stems = [os.path.splitext(os.path.basename(p))[0] for p in imgs]
    gts = load_gts(imgs, TEST_LBL)
    n = len(stems)
    print(f'\n{n} test images, {sum(len(g["cls"]) for g in gts.values())} GT lesions')

    need = {BASE} | {m for v in ENS.values() for m in v['members']}
    preds = {m: cached_pred(m, imgs, '_pred_') for m in need}
    for name, v in ENS.items():
        preds[name] = wbf_fuse(preds, gts, v['members'], v['weights'], IOU_THR, SKIP_THR)
    names = [BASE] + list(ENS.keys())
    D = {m: Dets(preds[m], gts, stems) for m in names}

    # sanity row (reference ensemble must reproduce the manuscript test numbers if weights are the same)
    r = metrics(D[REF], full=False)
    print(f'\nCHECK {REF}: P {r["P"]:.4f} R {r["R"]:.4f} F1 {r["F1"]:.4f} mAP50 {r["mAP50"]:.4f} '
          f'TP {r["TP"]:.0f} FP {r["FP"]:.0f} FN {r["FN"]:.0f}   (manuscript: 0.9286 0.6393 0.7573 0.8490 78 6 44)')

    # ---- sensitivity at matched FP/image (max sensitivity achievable at or below each FP rate) ----
    rows = []
    for sc, cl in SCOPES:
        for m in names:
            f, s = froc(D[m], cl)
            rows.append({'Scope': sc, 'Model': m, **{f'<= {x} FP/img': round(sens_at(f, s, x), 4) for x in FPI_GRID}})
    tf = pd.DataFrame(rows); tf.to_csv(f'{OUT}/froc_sensitivity_matched_fpi.csv', index=False)

    # ---- paired bootstrap of the sensitivity differences (same resamples for every model) ----
    rng = np.random.default_rng(SEED)
    IDX = rng.integers(0, n, (N_BOOT, n))
    WB = np.stack([np.bincount(r_, minlength=n) for r_ in IDX]).astype(float)
    boot = {(sc, m): np.zeros((N_BOOT, len(FPI_GRID))) for sc, _ in SCOPES for m in names}
    for b in range(N_BOOT):
        for sc, cl in SCOPES:
            for m in names:
                f, s = froc_w(D[m], WB[b], cl)
                boot[(sc, m)][b] = [sens_at(f, s, x) for x in FPI_GRID]
    prow = []
    for sc, cl in SCOPES:
        pt_base = {m: [sens_at(*froc(D[m], cl), x) for x in FPI_GRID] for m in names}
        for a, b_ in ((n_, ref) for n_ in ENS for ref in ([BASE] + [REF] if n_ != REF else [BASE]) if n_ != ref):
            for k, x in enumerate(FPI_GRID):
                dd = boot[(sc, a)][:, k] - boot[(sc, b_)][:, k]; lo, hi = pct(dd)
                prow.append({'Scope': sc, 'Model': a, 'Versus': b_, 'FP/img <=': x,
                             'Point diff': round(pt_base[a][k] - pt_base[b_][k], 4),
                             'Boot mean diff': round(float(dd.mean()), 4), '95% interval': f'{lo:+.4f} to {hi:+.4f}'})
    pp = pd.DataFrame(prow); pp.to_csv(f'{OUT}/froc_sensitivity_paired_bootstrap.csv', index=False)

    # ---- figure: FROC curves, 3 panels ----
    import matplotlib; matplotlib.use('Agg'); import matplotlib.pyplot as plt
    fig, axs = plt.subplots(1, 3, figsize=(15, 4.6), sharey=True)
    for ax, (sc, cl) in zip(axs, SCOPES):
        for m in names:
            f, s = froc(D[m], cl); ax.step(f, s, where='post', label=m)
        for x in FPI_GRID:
            ax.axvline(x, color='grey', lw=0.6, ls=':')
        ax.set_xlim(0, 3); ax.set_ylim(0, 1.02); ax.set_title(sc); ax.set_xlabel('False positives per image'); ax.grid(alpha=.3)
    axs[0].set_ylabel('Sensitivity'); axs[0].legend(fontsize=8, loc='lower right')
    fig.suptitle(f'FROC - {n} test images', fontweight='bold'); fig.tight_layout()
    fig.savefig(f'{OUT}/froc_matched_fpi.png', dpi=300); plt.close(fig)

    pd.set_option('display.width', 250); pd.set_option('display.max_columns', 30)
    print('\n=== TEST FROC: SENSITIVITY AT MATCHED FP/IMAGE ===\n', tf.to_string(index=False))
    print('\n=== PAIRED BOOTSTRAP (sensitivity differences) ===\n', pp.to_string(index=False))
    print('\nSaved to', OUT)


if __name__ == '__main__':
    main()